export type IconName = keyof typeof ICONS;

/** Every name in the set, in table order. */
export const ICON_NAMES = Object.keys(ICONS) as IconName[];

type Live = { id: string; key: string; s: Stroke; on: boolean; enter: boolean };
type State = { name: IconName; gen: number; live: Live[] };

const table = ICONS as Record<IconName, Record<string, Stroke>>;

/** Command letters and argument counts: `d` interpolates only when these match. */
const shape = (d: string) =>
  (d.match(/[a-zA-Z][^a-zA-Z]*/g) ?? []).map((c) => c[0] + ((c.slice(1).match(/-?[\d.]+(?:e-?\d+)?/g) ?? []).length)).join();

let morphD: boolean | undefined;
const canMorphD = () => (morphD ??= typeof CSS !== "undefined" && CSS.supports("d", 'path("M0 0")'));

function morphs(from: Stroke, to: Stroke) {
  if (Boolean(from.block) !== Boolean(to.block) || Boolean(from.cut) !== Boolean(to.cut)) return false;
  return from.d === to.d || (canMorphD() && shape(from.d) === shape(to.d));
}

function initial(name: IconName): State {
  return {
    name,
    gen: 0,
    live: Object.entries(table[name]).map(([key, s]) => ({ id: `${key}.0`, key, s, on: true, enter: false })),
  };
}

function next(prev: State, name: IconName): State {
  const want = table[name];
  const gen = prev.gen + 1;
  const taken = new Set<string>();
  const live: Live[] = [];
  for (const l of [...prev.live].sort((a, b) => Number(b.on) - Number(a.on))) {
    const s = want[l.key];
    if (s && !taken.has(l.key) && morphs(l.s, s)) {
      taken.add(l.key);
      live.push({ ...l, s, on: true, enter: !l.on });
    } else {
      live.push({ ...l, on: false, enter: false });
    }
  }
  for (const [key, s] of Object.entries(want)) {
    if (!taken.has(key)) live.push({ id: `${key}.${gen}`, key, s, on: true, enter: true });
  }
  const gone = live.filter((l) => !l.on);
  const drop = new Set(gone.slice(0, Math.max(0, gone.length - 8)).map((l) => l.id));
  return { name, gen, live: live.filter((l) => !drop.has(l.id)) };
}

const HIDE = 0.3;

// CSS `d` is set only after the first change; until then the attribute draws.
function dash(l: Live, morphing: boolean): CSSProperties | undefined {
  const f = l.s.f ?? 0;
  const t = l.s.t ?? 1;
  const len = t - f;
  const off = f === 0 ? len + HIDE : -(1 + HIDE);
  const style = {
    d: morphing ? `path("${l.s.d}")` : undefined,
    rotate: l.s.rot ? `${l.s.rot}deg` : undefined,
    "--len": len === 1 ? undefined : len,
    "--on": f === 0 ? undefined : -f,
    "--off": off === 1 + HIDE ? undefined : off,
  } as CSSProperties;
  return Object.values(style).some((v) => v !== undefined) ? style : undefined;
}

export type IconProps = Omit<ComponentProps<"svg">, "children"> & { name: IconName };

export function Icon({ name, className, ...props }: IconProps) {
  const [state, setState] = useState(() => initial(name));
  const mask = `icon-cut-${useId()}`;
  if (state.name !== name) setState(next(state, name));

  const cuts = state.live.filter((l) => l.s.cut);
  const path = (l: Live, extra?: string) => (
    <path
      key={l.id + (extra ?? "")}
      d={l.s.d}
      pathLength={1}
      className={[styles.stroke, l.s.block && styles.block, l.s.seam && styles.seam, l.s.fx && styles[l.s.fx], extra].filter(Boolean).join(" ")}
      data-off={l.on ? undefined : ""}
      data-enter={l.enter ? "" : undefined}
      style={dash(l, state.gen > 0)}
      onTransitionEnd={
        l.on || extra
          ? undefined
          : (e) => {
              if (e.propertyName === "stroke-dashoffset") {
                setState((s) => ({ ...s, live: s.live.filter((x) => x.id !== l.id || x.on) }));
              }
            }
      }
    />
  );

  return (
    // Size attributes keep it from drawing huge before CSS loads.
    <svg
      viewBox="0 0 16 16"
      width="16"
      height="16"
      aria-hidden="true"
      data-icon={name}
      data-ready={state.gen > 0 ? "" : undefined}
      className={className ? `${styles.icon} ${className}` : styles.icon}
      {...props}
    >
      {cuts.length > 0 && (
        <mask id={mask} maskUnits="userSpaceOnUse" x="0" y="0" width="16" height="16">
          <rect width="16" height="16" fill="white" stroke="none" />
          {cuts.map((l) => path(l, styles.cut))}
        </mask>
      )}
      <g mask={cuts.length > 0 ? `url(#${mask})` : undefined}>{state.live.filter((l) => !l.s.cut).map((l) => path(l))}</g>
      {cuts.map((l) => path(l))}
    </svg>
  );
}

@layer theme, base, components, utilities;

@layer components {
  /* 50, like the popovers: one opened inside the drawer portals later, so it stacks above. */
  .viewport {
    position: fixed;
    z-index: 50;
    inset: 0;
    pointer-events: none;
  }

  /* The scrim is a sibling, not ::backdrop any more, so it gets the timings too. */
  .backdrop,
  .drawer {
    --drawer-open: 420ms;
    --drawer-close: 280ms;
  }

  .drawer {
    --drawer-pad: var(--ui-space-5);
    --drawer-width: 420px;
    --drawer-safe: env(safe-area-inset-bottom, 0px);
    position: fixed;
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    border: 0;
    background: var(--ui-surface);
    color: var(--ui-foreground);
    font-family: var(--ui-font-sans);
    /* Visible so the sheet's ::after strip shows when pulled up; .frame clips instead. */
    overflow: visible;
    overscroll-behavior: contain;
    outline: none;
    pointer-events: auto;
    /* Base UI sets the swipe offsets while a finger drags the sheet. */
    transform: translate3d(var(--drawer-swipe-movement-x, 0px), var(--drawer-swipe-movement-y, 0px), 0);
    transition: transform var(--drawer-open) var(--ui-ease-expand);
  }

  /* Released short of dismissing: glide back. */
  .drawer[data-settled] {
    transition: transform var(--ui-dur-glide) var(--ui-ease-glide);
  }

  .drawer[data-swiping] {
    user-select: none;
    transition-duration: 0ms;
  }

  /* Off screen, clear of the shadow, so nothing of the panel shows. */
  .drawer[data-starting-style],
  .drawer[data-ending-style] {
    transform: translate3d(0, calc(100% + 24px), 0);
  }

  /* Keyed to data-from, which the component renders with the panel: Base
     UI's data-swipe-direction arrives a frame later, so on the first open
     the panel used to start from the wrong side and land almost at once. */
  .drawer[data-mode="side"][data-from="right"]:is([data-starting-style], [data-ending-style]) {
    transform: translate3d(calc(100% + 24px), 0, 0);
  }

  .drawer[data-mode="side"][data-from="left"]:is([data-starting-style], [data-ending-style]) {
    transform: translate3d(calc(-100% - 24px), 0, 0);
  }

  /* A flick hands over its speed: the faster the release, the shorter the exit. */
  .drawer[data-ending-style] {
    transition: transform calc(var(--drawer-close) * var(--drawer-swipe-strength, 1)) var(--ui-ease-expand);
  }

  .drawer[data-size="sm"] {
    --drawer-width: 360px;
  }

  .drawer[data-size="lg"] {
    --drawer-width: 560px;
  }

  .drawer[data-mode="side"] {
    inset-block: 0;
    inset-inline: auto 0;
    width: var(--drawer-width);
    max-width: calc(100% - var(--ui-space-7));
    height: 100dvh;
    max-height: none;
    /* The floating shadow carries the edge, on the open side too. */
    box-shadow: var(--ui-shadow-floating);
  }

  .drawer[data-mode="side"][data-side="start"] {
    inset-inline: 0 auto;
  }

  .drawer[data-mode="sheet"] {
    inset-inline: 0;
    inset-block: auto var(--drawer-keyboard, 0px);
    width: 100%;
    max-width: 640px;
    height: auto;
    max-height: calc(100dvh - var(--drawer-keyboard, 0px) - var(--ui-space-7));
    margin-inline: auto;
    border-start-start-radius: var(--ui-radius-lg);
    border-start-end-radius: var(--ui-radius-lg);
    /* The floating shadow carries the edge: one ring, so the top line is the
       same weight as every other box's. */
    box-shadow: var(--ui-shadow-floating);
  }

  .drawer[data-mode="sheet"][data-keyboard] {
    --drawer-safe: 0px;
  }

  .drawer[data-mode="sheet"]::after {
    content: "";
    position: absolute;
    inset-inline: 0;
    top: 100%;
    height: var(--ui-space-8);
    background: var(--ui-surface);
  }

  /* ---------- Scrim ---------- */

  .backdrop {
    position: fixed;
    z-index: 50;
    inset: 0;
    min-height: 100dvh;
    background: var(--ui-scrim);
    opacity: calc(1 - var(--drawer-swipe-progress, 0));
    transition: opacity var(--drawer-open) var(--ui-ease-expand);
  }

  .backdrop[data-starting-style],
  .backdrop[data-ending-style] {
    opacity: 0;
  }

  .backdrop[data-swiping] {
    transition-duration: 0ms;
  }

  .backdrop[data-ending-style] {
    transition-duration: calc(var(--drawer-close) * var(--drawer-swipe-strength, 1));
  }

  @media (prefers-reduced-motion: reduce) {
    .backdrop,
    .backdrop[data-ending-style] {
      transition-duration: var(--ui-dur-instant);
    }
    .drawer,
    .drawer[data-settled],
    .drawer[data-ending-style] {
      transition: opacity var(--ui-dur-instant) var(--ui-ease-enter);
    }
    .drawer[data-starting-style],
    .drawer[data-ending-style],
    .drawer[data-mode="side"]:is([data-starting-style], [data-ending-style]) {
      transform: none;
      opacity: 0;
    }
  }

  /* ---------- Layout ---------- */

  .frame {
    display: grid;
    /* Named rows, so an absent handle, body or footer doesn't shift the others. */
    grid-template-rows: [handle] auto [header] auto [body] minmax(0, 1fr) [footer] auto;
    height: 100%;
    max-height: inherit;
    border-radius: inherit;
    overflow: clip;
  }

  .drawer[data-mode="sheet"] .frame {
    height: auto;
  }

  .handle {
    display: none;
  }

  .drawer[data-mode="sheet"] .handle {
    display: block;
    grid-row: handle;
    justify-self: center;
    width: var(--ui-space-6);
    height: var(--ui-space-1);
    margin-block-start: var(--ui-space-2);
    border-radius: var(--ui-radius-full);
    background: color-mix(in oklch, var(--ui-foreground) 16%, transparent);
  }

  .header {
    grid-row: header;
    position: relative;
    display: flex;
    align-items: flex-start;
    gap: var(--ui-space-3);
    padding: var(--drawer-pad) var(--drawer-pad) var(--ui-space-4);
  }

  .drawer[data-mode="sheet"] .header {
    padding-block-start: var(--ui-space-3);
  }

  .drawer[data-mode="sheet"] :is(.handle, .header, .footer) {
    touch-action: none;
  }

  .heading {
    display: grid;
    flex: 1;
    gap: var(--ui-space-1);
    min-width: 0;
    padding-top: var(--ui-space-1);
  }

  .title {
    margin: 0;
    color: var(--ui-foreground);
    font-family: var(--ui-font-display);
    font-size: var(--ui-text-2xl);
    font-weight: var(--ui-weight-semibold);
    line-height: var(--ui-leading-2xl);
    letter-spacing: var(--ui-tracking-heading);
    text-wrap: balance;
  }

  .description {
    margin: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-md);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  .close {
    --close-size: var(--ui-control-sm);
    display: grid;
    place-items: center;
    flex-shrink: 0;
    --close-width: calc(var(--close-size) * var(--ui-capsule));
    width: var(--close-width);
    height: var(--close-size);
    margin-block-start: calc(var(--ui-space-1) + var(--ui-leading-2xl) / 2 - var(--close-size) / 2);
    margin-inline-end: calc((16px - var(--close-width)) / 2);
    padding: 0;
    border: 0;
    border-radius: var(--ui-radius-full);
    background: transparent;
    color: var(--ui-muted);
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      color var(--ui-dur-instant) var(--ui-ease-color),
      scale var(--ui-dur-snap) var(--ui-ease-snap);
  }

  .close svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    stroke-width: var(--ui-icon-stroke-medium);
    pointer-events: none;
  }

  @media (hover: hover) {
    .close:hover {
      background: var(--ui-fill);
      color: var(--ui-foreground);
    }
  }

  .close:active {
    background: var(--ui-fill-strong);
    scale: var(--ui-scale-press);
    transition-duration: var(--ui-dur-press);
  }

  .close:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  @media (pointer: coarse) {
    .close {
      --close-size: var(--ui-control-md);
    }
  }

  .body {
    grid-row: body;
    min-height: 0;
    padding: var(--ui-space-1) var(--drawer-pad) var(--drawer-pad);
    overflow-y: auto;
    overscroll-behavior: contain;
    color: var(--ui-foreground);
    font-size: var(--ui-text-md);
    line-height: var(--ui-leading-md);
  }

  .drawer[data-mode="sheet"] .body:last-child {
    padding-block-end: calc(var(--drawer-pad) + var(--drawer-safe));
  }

  .footer {
    grid-row: footer;
    position: relative;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-end;
    gap: var(--ui-space-2) var(--ui-space-3);
    padding: var(--ui-space-4) var(--drawer-pad);
  }

  .drawer[data-mode="sheet"] .footer {
    padding-block-end: max(var(--ui-space-4), var(--drawer-safe));
  }

  .header + .footer {
    padding-block-start: var(--ui-space-2);
  }

  .header::after,
  .footer::before {
    content: "";
    position: absolute;
    inset-inline: 0;
    height: var(--ui-hairline);
    background: var(--ui-border);
    pointer-events: none;
  }

  .header::after {
    bottom: 0;
    opacity: 0;
  }

  .footer::before {
    top: 0;
  }

  .header + .footer::before {
    content: none;
  }

  @supports (timeline-scope: --a) {
    .frame {
      timeline-scope: --drawer-scroll;
    }

    .body {
      scroll-timeline: --drawer-scroll block;
    }

    .header::after {
      animation: drawer-edge-in linear both;
      animation-timeline: --drawer-scroll;
      animation-range: 0 var(--ui-space-4);
    }

    .footer::before {
      animation: drawer-edge-out linear both;
      animation-timeline: --drawer-scroll;
      animation-range: calc(100% - var(--ui-space-4)) 100%;
    }
  }

  /* Chromium keeps an animation's last value once its scroll timeline goes inactive,
     so a body that now fits would keep stale edges. The script sets data-fits. */
  .frame:has(> .body[data-fits]) .header::after,
  .frame:has(> .body[data-fits]) .footer::before {
    animation: none;
  }

  @keyframes drawer-edge-in {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }

  @keyframes drawer-edge-out {
    from {
      opacity: 1;
    }
    to {
      opacity: 0;
    }
  }

  .actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: var(--ui-space-2);
    margin-inline-start: auto;
  }

  .drawer[data-mode="sheet"] .actions {
    flex: 1 1 100%;
  }

  .drawer[data-mode="sheet"] .actions > * {
    flex: 1 1 0;
  }

  @media (prefers-reduced-motion: reduce) {
    .close:active {
      scale: none;
    }
  }
}

"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useState,
  useSyncExternalStore,
  type ReactNode,
  type RefObject,
} from "react";
import { Drawer as BaseDrawer } from "@base-ui/react/drawer";
import { Icon } from "../icons/icons";
import styles from "./drawer.module.css";

const FOCUSABLE = [
  "[autofocus]",
  "input:not([type=hidden]):not(:disabled)",
  "select:not(:disabled)",
  "textarea:not(:disabled)",
  "button:not(:disabled)",
  "a[href]",
  "[contenteditable=true]",
  "[tabindex]:not([tabindex='-1'])",
].join(",");

function firstFocusable(root: Element | null) {
  if (!root) return null;
  const autofocus = root.querySelector<HTMLElement>("[autofocus]");
  if (autofocus) return autofocus;
  for (const el of root.querySelectorAll<HTMLElement>(FOCUSABLE)) {
    if (!el.closest("[inert]") && el.getClientRects().length) return el;
  }
  return null;
}

const TEXT_ENTRY = /^(text|search|email|url|tel|password|number|date|time|datetime-local|month|week)$/;

function isTextEntry(el: HTMLElement) {
  if (el instanceof HTMLTextAreaElement || el.isContentEditable) return true;
  return el instanceof HTMLInputElement && TEXT_ENTRY.test(el.type);
}

/** The nearest themed subtree, so the portaled panel keeps its tokens. */
function themeRoot(el: Element | null) {
  const root = el?.closest<HTMLElement>("[data-theme]");
  return root && root !== document.documentElement ? root : undefined;
}

/** Media query under which the drawer becomes a bottom sheet. */
export const SHEET_QUERY = "(max-width: 640px), (pointer: coarse) and (max-height: 500px)";

function subscribe(onChange: () => void) {
  const query = matchMedia(SHEET_QUERY);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
}

function useSheetQuery() {
  return useSyncExternalStore(
    subscribe,
    () => matchMedia(SHEET_QUERY).matches,
    () => false,
  );
}

export type DrawerProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: ReactNode;
  description?: ReactNode;
  children?: ReactNode;
  footer?: ReactNode;
  /** Logical edge on wider screens; `bottom` makes it a sheet everywhere. */
  side?: "end" | "start" | "bottom";
  size?: "sm" | "md" | "lg";
  /** Focus target on open. Defaults to the first control in the body. */
  initialFocus?: RefObject<HTMLElement | null>;
  /** Focus returns here on close. Defaults to the element focused at open. */
  triggerRef?: RefObject<HTMLElement | null>;
  /** Focus target on close when the trigger is gone. */
  finalFocus?: RefObject<HTMLElement | null>;
  /** Blocks every way of dismissing, e.g. while saving. */
  locked?: boolean;
  className?: string;
};

/** A modal panel from the screen edge; a draggable bottom sheet on phones. Built on Base UI's Drawer. */
export function Drawer({
  open,
  onOpenChange,
  title,
  description,
  children,
  footer,
  side = "end",
  size = "md",
  initialFocus,
  triggerRef,
  finalFocus,
  locked = false,
  className,
}: DrawerProps) {
  const narrow = useSheetQuery();
  const sheet = side === "bottom" || narrow;

  const [popup, setPopup] = useState<HTMLDivElement | null>(null);
  const [body, setBody] = useState<HTMLDivElement | null>(null);
  const [footerEl, setFooterEl] = useState<HTMLDivElement | null>(null);
  // Set once the entrance has finished, so a drag released short of dismissing glides back.
  const [settled, setSettled] = useState(false);
  const [rtl, setRtl] = useState(false);

  // The element that opened it, read as `open` turns true, before Base UI
  // mounts the panel and moves focus inside.
  const [trigger, setTrigger] = useState<HTMLElement | null>(null);
  useLayoutEffect(() => {
    if (!open) return;
    const active = document.activeElement;
    const from = triggerRef?.current ?? (active instanceof HTMLElement && active !== document.body ? active : null);
    setTrigger(from);
    setRtl(getComputedStyle(from ?? document.documentElement).direction === "rtl");
  }, [open, triggerRef]);

  const swipeDirection = sheet ? "down" : (side === "start") === rtl ? "right" : "left";

  // Mobile keyboards cover the page without resizing it; lift the sheet by the
  // covered height. Pinch zoom also shrinks the visual viewport, so ignore it.
  useEffect(() => {
    const viewport = window.visualViewport;
    if (!open || !sheet || !popup || !viewport) return;
    function update() {
      const covered = viewport!.scale > 1.01 ? 0 : window.innerHeight - viewport!.height - viewport!.offsetTop;
      if (covered > 1) {
        popup!.style.setProperty("--drawer-keyboard", `${Math.round(covered)}px`);
        popup!.setAttribute("data-keyboard", "");
      } else {
        popup!.style.removeProperty("--drawer-keyboard");
        popup!.removeAttribute("data-keyboard");
      }
    }
    update();
    viewport.addEventListener("resize", update);
    viewport.addEventListener("scroll", update);
    return () => {
      viewport.removeEventListener("resize", update);
      viewport.removeEventListener("scroll", update);
      popup.style.removeProperty("--drawer-keyboard");
      popup.removeAttribute("data-keyboard");
    };
  }, [open, sheet, popup]);

  // data-fits works around a Chromium scroll-timeline bug (see the CSS).
  const markFits = useCallback((el: HTMLDivElement | null) => {
    el?.toggleAttribute("data-fits", el.scrollHeight <= el.clientHeight);
  }, []);
  useEffect(() => {
    if (!body) return;
    markFits(body);
    const observer = new ResizeObserver(() => markFits(body));
    observer.observe(body);
    return () => observer.disconnect();
  }, [body, markFits]);

  function dismiss() {
    if (locked) return;
    onOpenChange(false);
  }

  return (
    <BaseDrawer.Root
      open={open}
      onOpenChange={(next) => {
        // Controlled: `locked` (or the owner) can keep it open.
        if (!next) dismiss();
      }}
      onOpenChangeComplete={(isOpen) => setSettled(isOpen)}
      swipeDirection={swipeDirection}
    >
      <BaseDrawer.Portal container={themeRoot(trigger)}>
        <BaseDrawer.Backdrop className={styles.backdrop} />
        <BaseDrawer.Viewport className={styles.viewport}>
          <BaseDrawer.Popup
            ref={setPopup}
            className={className ? `${styles.drawer} ${className}` : styles.drawer}
            data-mode={sheet ? "sheet" : "side"}
            data-side={side === "start" ? "start" : "end"}
            data-from={sheet ? "bottom" : swipeDirection === "right" ? "right" : "left"}
            data-size={size}
            data-settled={settled || undefined}
            initialFocus={() => {
              let el = initialFocus?.current ?? firstFocusable(body) ?? firstFocusable(footerEl);
              // Focusing a field while the sheet rises throws the keyboard over it.
              if (!initialFocus?.current && sheet && el && isTextEntry(el)) el = null;
              return el ?? popup ?? true;
            }}
            finalFocus={() => {
              if (trigger?.isConnected) return trigger;
              return finalFocus?.current ?? true;
            }}
          >
            {/* Side panels and a locked drawer don't swipe; a sheet does. */}
            <div className={styles.frame} data-base-ui-swipe-ignore={!sheet || locked ? "" : undefined}>
              <div className={styles.handle} aria-hidden="true" />
              <header className={styles.header}>
                <div className={styles.heading}>
                  <BaseDrawer.Title className={styles.title}>{title}</BaseDrawer.Title>
                  {description && (
                    <BaseDrawer.Description className={styles.description}>{description}</BaseDrawer.Description>
                  )}
                </div>
                <BaseDrawer.Close className={styles.close} aria-label="Close">
                  <Icon name="close" />
                </BaseDrawer.Close>
              </header>

              {/* Content: a mouse drag here selects text instead of moving the sheet. */}
              {children && (
                <BaseDrawer.Content
                  ref={setBody}
                  className={styles.body}
                  onScroll={(e) => markFits(e.currentTarget)}
                >
                  {children}
                </BaseDrawer.Content>
              )}

              {footer && (
                <div ref={setFooterEl} className={styles.footer}>
                  {footer}
                </div>
              )}
            </div>
          </BaseDrawer.Popup>
        </BaseDrawer.Viewport>
      </BaseDrawer.Portal>
    </BaseDrawer.Root>
  );
}

/** Footer button row; on a sheet the buttons share the width. */
export function DrawerActions({ children }: { children: ReactNode }) {
  return <div className={styles.actions}>{children}</div>;
}

@layer theme, base, components, utilities;

/* ---------- Busy ---------- */

@property --menu-dim {
  syntax: "<number>";
  inherits: false;
  initial-value: 1;
}

@layer components {
  /* Base UI places this; the surface inside animates. */
  .positioner {
    z-index: 50;
    outline: none;
  }

  .surface {
    position: relative;
    box-sizing: border-box;
    width: max-content;
    min-width: 220px;
    max-width: min(320px, calc(100vw - 16px));
    max-height: min(calc(100dvh - 16px), var(--available-height, 100dvh));
    /* Rows sit one inset in from the panel and take its concentric radius:
       a rounded row, not a pill, with its text a full --ui-pad-row in. */
    --menu-inset: var(--ui-inset-menu);
    --menu-row-radius: calc(var(--ui-radius-lg) - var(--menu-inset));
    padding: var(--menu-inset);
    overflow-y: auto;
    overscroll-behavior: contain;
    border-radius: var(--ui-radius-lg);
    background: var(--ui-surface);
    box-shadow: var(--ui-shadow-floating);
    color: var(--ui-foreground);
    font: var(--ui-weight-regular) var(--ui-text-md) / var(--ui-leading-md) var(--ui-font-sans);
    --ui-icon-stroke: var(--ui-icon-stroke-regular);
    user-select: none;
    outline: none;
    transform-origin: var(--transform-origin);
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter),
      scale var(--ui-dur-fast) var(--ui-ease-enter),
      filter var(--ui-dur-fast) var(--ui-ease-enter);
  }

  .surface[data-starting-style],
  .surface[data-ending-style] {
    opacity: 0;
    scale: 0.97;
    filter: blur(2px);
  }

  .surface[data-ending-style] {
    transition-duration: var(--ui-dur-instant);
    transition-timing-function: var(--ui-ease-exit);
  }

  .highlight {
    position: absolute;
    top: 0;
    left: var(--menu-inset);
    right: var(--menu-inset);
    border-radius: var(--menu-row-radius);
    background: var(--ui-fill-strong);
    opacity: 0;
    pointer-events: none;
    transition:
      translate var(--ui-dur-snap) var(--ui-ease-snap),
      opacity var(--ui-dur-instant) var(--ui-ease-color),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .highlight[data-visible] {
    opacity: 1;
  }

  .highlight[data-jump] {
    transition-property: opacity, background-color;
  }

  .highlight[data-tone="danger"] {
    background: var(--ui-danger-tint);
  }

  .surface:has(.item:active:not([data-disabled], [aria-busy])) > .highlight {
    background: color-mix(in oklch, var(--ui-foreground) 16%, transparent);
    transition-duration: var(--ui-dur-press);
  }

  .surface:has(.item[data-tone="danger"]:active) > .highlight {
    background: color-mix(in oklch, var(--ui-danger) 20%, transparent);
  }

  .item {
    position: relative;
    display: flex;
    align-items: flex-start;
    gap: var(--ui-space-3);
    padding: var(--ui-space-2) var(--ui-pad-row);
    border-radius: var(--menu-row-radius);
    outline: none;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
  }

  .item[data-tone="danger"] {
    color: var(--ui-danger-text);
  }

  .item[data-disabled] {
    opacity: 0.5;
    cursor: default;
  }

  .leading {
    display: none;
    flex-shrink: 0;
    place-items: center;
    width: 16px;
    height: var(--ui-leading-md);
    color: var(--ui-muted);
  }

  .item[data-tone="danger"] .leading {
    color: inherit;
  }

  .surface:has(.leading[data-filled]) .leading {
    display: grid;
  }

  .leading svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    stroke-width: var(--ui-icon-stroke);
  }

  .indicator {
    display: grid;
    place-items: center;
    width: 16px;
    height: 16px;
    color: var(--ui-foreground);
  }

  .dot[data-checked]::before {
    content: "";
    width: 6px;
    height: 6px;
    border-radius: var(--ui-radius-full);
    background: currentColor;
  }

  .text {
    display: grid;
    flex: 1;
    min-width: 0;
  }

  .item[aria-busy] {
    cursor: default;
  }

  .item[aria-busy] .label {
    --menu-dim: 1;
    /* Room inside the mask for descenders, given back so nothing moves. */
    margin-block: -4px;
    padding-block: var(--ui-space-1);
    mask-image: linear-gradient(
      90deg,
      rgb(0 0 0 / var(--menu-dim)) 35%,
      #000 50%,
      rgb(0 0 0 / var(--menu-dim)) 65%
    );
    mask-size: 300% 100%;
    mask-repeat: no-repeat;
    animation:
      menu-dim var(--ui-dur-base) var(--ui-ease-color) 120ms forwards,
      menu-sweep var(--ui-dur-sweep) linear 120ms infinite;
  }

  @keyframes menu-dim {
    to {
      --menu-dim: 0.4;
    }
  }

  @keyframes menu-sweep {
    from {
      mask-position: 100% 0;
    }
    to {
      mask-position: 0 0;
    }
  }

  .description {
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    text-wrap: pretty;
  }

  .shortcut {
    flex-shrink: 0;
    margin-inline-start: var(--ui-space-4);
    color: var(--ui-subtle);
    font-family: var(--ui-font-mono);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-regular);
    line-height: var(--ui-leading-md);
  }

  .chevron {
    flex-shrink: 0;
    width: var(--ui-icon-chevron);
    height: var(--ui-icon-chevron);
    margin-block-start: calc((var(--ui-leading-md) - 16px) / 2);
    margin-inline-start: var(--ui-space-4);
    margin-inline-end: -4px;
    color: var(--ui-subtle);
  }

  .group {
    display: grid;
  }

  .groupLabel {
    padding: var(--ui-space-2) var(--ui-pad-row) var(--ui-space-1);
    color: var(--ui-subtle);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-sm);
  }

  .separator {
    height: var(--ui-hairline);
    margin: var(--ui-space-2) calc(-1 * var(--menu-inset));
    background: var(--ui-border);
  }

  @media (pointer: coarse) {
    .item {
      padding-block: calc((var(--ui-control-lg) - var(--ui-leading-md)) / 2);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .surface {
      transition: none;
    }
    .surface {
      scale: none;
    }
    .highlight {
      transition-property: opacity, background-color;
    }
    .item[aria-busy] .label {
      --menu-dim: 0.5;
      animation: none;
    }
  }
}

"use client";

import {
  createContext,
  use,
  useCallback,
  useLayoutEffect,
  useRef,
  useState,
  useId,
  type ReactElement,
  type ReactNode,
} from "react";
import { Menu as BaseMenu } from "@base-ui/react/menu";
import { Icon } from "../icons/icons";
import { TextMorph } from "../text-morph/text-morph";
import styles from "./dropdown-menu.module.css";

/* Behavior (focus, keyboard, typeahead, submenus and their safe triangle,
   dismissal, positioning) comes from Base UI's Menu. This file keeps the look:
   one highlight that slides between items, the held width, busy and morphing
   labels. */

type Side = "top" | "bottom" | "left" | "right";
type Align = "start" | "center" | "end";

type RootApi = { close: () => void };

const RootContext = createContext<RootApi | null>(null);
/** The themed subtree the trigger sits in, so portalled panels keep its tokens. */
const ContainerContext = createContext<HTMLElement | undefined>(undefined);

function useRoot() {
  const ctx = use(RootContext);
  if (!ctx) throw new Error("Menu items must be inside <DropdownMenu>.");
  return ctx;
}

const ITEM = "[data-menu-item]";

/** Moves the panel's one highlight under its highlighted item. */
function placeHighlight(popup: HTMLElement, bar: HTMLElement) {
  // Submenus are portalled, so every item in here belongs to this panel.
  // An open submenu's trigger keeps the highlight while its submenu has focus.
  const item =
    popup.querySelector<HTMLElement>(`${ITEM}[data-highlighted]`) ??
    popup.querySelector<HTMLElement>(`${ITEM}[data-popup-open]`);
  if (!item) {
    bar.removeAttribute("data-visible");
    return;
  }
  const jump = !bar.hasAttribute("data-visible");
  if (jump) bar.setAttribute("data-jump", "");
  bar.style.translate = `0 ${item.offsetTop}px`;
  bar.style.height = `${item.offsetHeight}px`;
  bar.dataset.tone = item.dataset.tone ?? "";
  bar.setAttribute("data-visible", "");
  if (jump) {
    bar.getBoundingClientRect();
    bar.removeAttribute("data-jump");
  }
}

/* ---------- Panel ---------- */

type PanelProps = {
  side: Side | "inline-end";
  align: Align;
  sideOffset: number;
  alignOffset?: number;
  className?: string;
  children: ReactNode;
};

function MenuPanel({ side, align, sideOffset, alignOffset = 0, className, children }: PanelProps) {
  const container = use(ContainerContext);
  return (
    <BaseMenu.Portal container={container}>
      <BaseMenu.Positioner
        className={styles.positioner}
        side={side}
        align={align}
        sideOffset={sideOffset}
        alignOffset={alignOffset}
        collisionPadding={8}
      >
        <BaseMenu.Popup className={className ? `${styles.surface} ${className}` : styles.surface}>
          <Highlight />
          {children}
        </BaseMenu.Popup>
      </BaseMenu.Positioner>
    </BaseMenu.Portal>
  );
}

/** Mounts with the popup, each time it opens. */
function Highlight() {
  const barRef = useRef<HTMLSpanElement>(null);

  // Hold the popup's width from now on, so a relabelled item never pulls the
  // edge in under the pointer; and keep the bar under whichever item Base UI
  // marks highlighted.
  useLayoutEffect(() => {
    const bar = barRef.current;
    const popup = bar?.parentElement;
    if (!bar || !popup) return;
    popup.style.minWidth = `${popup.offsetWidth}px`;
    placeHighlight(popup, bar);
    const observer = new MutationObserver(() => placeHighlight(popup, bar));
    observer.observe(popup, { subtree: true, attributes: true, attributeFilter: ["data-highlighted", "data-popup-open"] });
    return () => observer.disconnect();
  }, []);

  return <span ref={barRef} className={styles.highlight} aria-hidden="true" />;
}

/* ---------- Root ---------- */

type DropdownMenuProps = {
  /** A button. It gets aria-haspopup, aria-expanded and aria-controls. */
  trigger: ReactElement;
  side?: Side;
  align?: Align;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
  children: ReactNode;
};

export function DropdownMenu({
  trigger,
  side = "bottom",
  align = "start",
  open,
  onOpenChange,
  className,
  children,
}: DropdownMenuProps) {
  const actionsRef = useRef<BaseMenu.Root.Actions | null>(null);
  const [triggerEl, setTriggerEl] = useState<HTMLElement | null>(null);
  const container = triggerEl?.closest<HTMLElement>("[data-theme]") ?? undefined;
  const close = useCallback(() => actionsRef.current?.close(), []);

  return (
    <RootContext value={{ close }}>
      <ContainerContext value={container}>
        <BaseMenu.Root
          open={open}
          onOpenChange={(next) => onOpenChange?.(next)}
          actionsRef={actionsRef}
          modal={false}
        >
          <BaseMenu.Trigger ref={setTriggerEl} render={trigger} />
          <MenuPanel side={side} align={align} sideOffset={6} className={className}>
            {children}
          </MenuPanel>
        </BaseMenu.Root>
      </ContainerContext>
    </RootContext>
  );
}

/* ---------- Items ---------- */

type ItemCommon = {
  children: ReactNode;
  disabled?: boolean;
  icon?: ReactNode;
  /** A shortcut hint like "⌘D". Visual only. */
  shortcut?: string;
  /** The same shortcut for assistive tech, like "Meta+D". */
  keyshortcuts?: string;
  description?: ReactNode;
};

type ItemBodyProps = Omit<ItemCommon, "disabled" | "keyshortcuts"> & {
  id: string;
  leading?: ReactNode;
  /** Changes in place while the menu stays open; a string morphs. */
  morph?: boolean;
  trailing?: ReactNode;
};

function ItemBody({ id, leading, icon, shortcut, description, morph = false, trailing, children }: ItemBodyProps) {
  const morphing = morph && typeof children === "string";
  return (
    <>
      <span className={styles.leading} data-filled={leading || icon ? "" : undefined} aria-hidden="true">
        {leading ?? icon}
      </span>
      <span className={styles.text}>
        <span id={`${id}-label`} className={styles.label}>
          {morphing ? <TextMorph>{children as string}</TextMorph> : children}
        </span>
        {description && (
          <span id={`${id}-description`} className={styles.description}>
            {description}
          </span>
        )}
      </span>
      {shortcut && (
        <kbd className={styles.shortcut} aria-hidden="true">
          {shortcut}
        </kbd>
      )}
      {trailing}
    </>
  );
}

/** Props every item element shares. */
function itemProps(id: string, { children, description, keyshortcuts }: Pick<ItemCommon, "children" | "description" | "keyshortcuts">) {
  return {
    id,
    className: styles.item,
    "data-menu-item": "",
    // Typeahead reads this; a morphing label renders its text twice.
    label: typeof children === "string" ? children : undefined,
    "aria-labelledby": `${id}-label`,
    "aria-describedby": description ? `${id}-description` : undefined,
    "aria-keyshortcuts": keyshortcuts,
  };
}

type MenuItemProps = ItemCommon & {
  /** Runs when chosen; gets `close` when `closeOnSelect={false}`. */
  onSelect?: (menu: { close: () => void }) => void;
  /** `danger` for destructive actions like delete. */
  variant?: "default" | "danger";
  /** `false` keeps the menu open so the item can confirm in place. */
  closeOnSelect?: boolean;
  /** Work is running: presses are ignored and focus stays. */
  busy?: boolean;
};

export function MenuItem({
  onSelect,
  variant = "default",
  closeOnSelect = true,
  busy = false,
  disabled = false,
  ...props
}: MenuItemProps) {
  const root = useRoot();
  const id = useId();
  return (
    <BaseMenu.Item
      {...itemProps(id, props)}
      disabled={disabled}
      // Busy isn't disabled: it keeps focus but ignores presses.
      closeOnClick={closeOnSelect && !busy}
      data-tone={variant === "danger" ? "danger" : undefined}
      aria-busy={busy || undefined}
      onClick={() => {
        if (!busy) onSelect?.({ close: root.close });
      }}
    >
      <ItemBody id={id} {...props} morph={!closeOnSelect} />
    </BaseMenu.Item>
  );
}

type MenuCheckboxItemProps = ItemCommon & {
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
  /** Checkboxes keep the menu open by default. */
  closeOnSelect?: boolean;
};

export function MenuCheckboxItem({
  checked,
  onCheckedChange,
  closeOnSelect = false,
  disabled = false,
  ...props
}: MenuCheckboxItemProps) {
  const id = useId();
  return (
    <BaseMenu.CheckboxItem
      {...itemProps(id, props)}
      disabled={disabled}
      checked={checked}
      onCheckedChange={(next) => onCheckedChange(next)}
      closeOnClick={closeOnSelect}
    >
      <ItemBody
        id={id}
        {...props}
        leading={<span className={styles.indicator}>{checked && <Icon name="check" />}</span>}
      />
    </BaseMenu.CheckboxItem>
  );
}

type MenuRadioGroupProps = {
  value: string;
  onValueChange: (value: string) => void;
  /** Shown above the options and used as the group's name. */
  label?: string;
  children: ReactNode;
};

export function MenuRadioGroup({ value, onValueChange, label, children }: MenuRadioGroupProps) {
  return (
    <BaseMenu.RadioGroup
      className={styles.group}
      value={value}
      onValueChange={(next: string) => onValueChange(next)}
    >
      {label && <BaseMenu.GroupLabel className={styles.groupLabel}>{label}</BaseMenu.GroupLabel>}
      {children}
    </BaseMenu.RadioGroup>
  );
}

type MenuRadioItemProps = ItemCommon & {
  value: string;
  /** Radios close the menu by default. */
  closeOnSelect?: boolean;
};

export function MenuRadioItem({ value, closeOnSelect = true, disabled = false, ...props }: MenuRadioItemProps) {
  const id = useId();
  return (
    <BaseMenu.RadioItem {...itemProps(id, props)} value={value} disabled={disabled} closeOnClick={closeOnSelect}>
      <ItemBody
        id={id}
        {...props}
        leading={<BaseMenu.RadioItemIndicator keepMounted className={`${styles.indicator} ${styles.dot}`} />}
      />
    </BaseMenu.RadioItem>
  );
}

export function MenuGroup({ label, children }: { label?: string; children: ReactNode }) {
  return (
    <BaseMenu.Group className={styles.group}>
      {label && <BaseMenu.GroupLabel className={styles.groupLabel}>{label}</BaseMenu.GroupLabel>}
      {children}
    </BaseMenu.Group>
  );
}

export function MenuSeparator() {
  return <BaseMenu.Separator className={styles.separator} />;
}

type MenuSubProps = Omit<ItemCommon, "shortcut" | "keyshortcuts" | "children"> & {
  label: ReactNode;
  children: ReactNode;
};

export function MenuSub({ label, icon, description, disabled = false, children }: MenuSubProps) {
  const id = useId();
  return (
    <BaseMenu.SubmenuRoot>
      <BaseMenu.SubmenuTrigger {...itemProps(id, { children: label, description })} disabled={disabled}>
        <ItemBody
          id={id}
          icon={icon}
          description={description}
          trailing={<Icon className={styles.chevron} name="chevron-right" />}
        >
          {label}
        </ItemBody>
      </BaseMenu.SubmenuTrigger>
      {/* Lines the submenu's first item up with its trigger. */}
      <MenuPanel side="inline-end" align="start" sideOffset={4} alignOffset={-8}>
        {children}
      </MenuPanel>
    </BaseMenu.SubmenuRoot>
  );
}

@layer theme, base, components, utilities;

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  .root {
    --kbd-line: var(--ui-leading-md);
    --kbd-height: calc(var(--kbd-line) - 2px);
    --kbd-pad: 5px;

    display: inline-grid;
    justify-items: var(--kbd-align, center);
    align-items: center;
    font: inherit;
    white-space: nowrap;
  }

  /* `top`, not `middle`: middle centers on the x-height and makes the line taller. */
  .root[data-variant="caps"] {
    height: var(--kbd-line);
    vertical-align: top;
  }

  .root[data-size="sm"] {
    --kbd-line: var(--ui-leading-sm);
    --kbd-pad: 4px;
  }

  .spelling {
    grid-area: 1 / 1;
    display: inline-flex;
    min-width: 0;
  }

  /* Holds its width unseen until the platform stylesheet decides (see kbd.tsx). */
  .spelling[data-kbd-spelling="apple"] {
    visibility: hidden;
  }

  .keys {
    display: inline-flex;
    align-items: center;
    gap: 2px;
  }

  .key {
    display: inline-grid;
    place-items: center;
    box-sizing: border-box;
    /* A single key is a short pill, never a circle: the same shape as a
       button, just smaller. */
    min-width: calc(var(--kbd-height) * 1.5);
    height: var(--kbd-height);
    padding-inline: var(--kbd-pad);
    border-radius: var(--ui-radius-full);
    background: color-mix(in oklch, currentColor 7%, transparent);
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-border-strong);
    font-family: var(--ui-font-sans);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-medium);
    font-style: normal;
    line-height: 1;
  }

  .root[data-variant="plain"] .keys {
    gap: 0;
    font-variant-numeric: tabular-nums;
  }

  @media (forced-colors: active) {
    .key {
      border: 1px solid CanvasText;
    }
  }
}

"use client";

import { useSyncExternalStore, type ComponentProps } from "react";
import styles from "./kbd.module.css";

type Platform = "apple" | "other";

/* [drawn, read] on Apple, then elsewhere. */
const KEYS: Record<string, [[string, string], [string, string]]> = {
  mod: [["⌘", "Command"], ["Ctrl", "Control"]],
  cmd: [["⌘", "Command"], ["⌘", "Command"]],
  ctrl: [["⌃", "Control"], ["Ctrl", "Control"]],
  alt: [["⌥", "Option"], ["Alt", "Alt"]],
  option: [["⌥", "Option"], ["Alt", "Alt"]],
  shift: [["⇧", "Shift"], ["Shift", "Shift"]],
  enter: [["↵", "Return"], ["↵", "Enter"]],
  return: [["↵", "Return"], ["↵", "Enter"]],
  backspace: [["⌫", "Delete"], ["⌫", "Backspace"]],
  delete: [["⌦", "Forward delete"], ["Del", "Delete"]],
  tab: [["Tab", "Tab"], ["Tab", "Tab"]],
  esc: [["esc", "Escape"], ["esc", "Escape"]],
  escape: [["esc", "Escape"], ["esc", "Escape"]],
  space: [["Space", "Space"], ["Space", "Space"]],
  up: [["↑", "Up arrow"], ["↑", "Up arrow"]],
  down: [["↓", "Down arrow"], ["↓", "Down arrow"]],
  left: [["←", "Left arrow"], ["←", "Left arrow"]],
  right: [["→", "Right arrow"], ["→", "Right arrow"]],
};

function key(name: string, platform: Platform): [string, string] {
  const known = KEYS[name.toLowerCase()];
  if (known) return known[platform === "apple" ? 0 : 1];
  const shown = name.length === 1 ? name.toUpperCase() : name;
  return [shown, shown];
}

/* Adds a <head> stylesheet before first paint that picks a spelling. Not an <html>
   attribute: hydration tolerates extra <head> nodes but reports attributes. */
const STYLE_ID = "kbd-platform";
const SCRIPT = `(function(){if(document.getElementById("${STYLE_ID}"))return;var a=/mac|iphone|ipad|ipod/i.test((navigator.userAgentData&&navigator.userAgentData.platform)||navigator.platform||navigator.userAgent),s=document.createElement("style");s.id="${STYLE_ID}";s.textContent="[data-kbd-spelling="+(a?"other":"apple")+"]{display:none!important}[data-kbd-spelling="+(a?"apple":"other")+"]{visibility:visible!important}";document.head.appendChild(s)})()`;

// Keep in sync with the test in SCRIPT.
function detect(): Platform {
  const nav = navigator as Navigator & { userAgentData?: { platform?: string } };
  // iPadOS reports itself as a Mac, which is right here: same keys.
  return /mac|iphone|ipad|ipod/i.test(nav.userAgentData?.platform || nav.platform || nav.userAgent) ? "apple" : "other";
}

// No stylesheet yet (script blocked, or no server Kbd): painted Kbds only change visibility.
if (typeof document !== "undefined" && !document.getElementById(STYLE_ID)) {
  const shown = detect();
  const hidden = shown === "apple" ? "other" : "apple";
  const painted = document.querySelector("[data-kbd-spelling]") !== null;
  const style = document.createElement("style");
  style.id = STYLE_ID;
  style.textContent =
    `[data-kbd-spelling=${hidden}]{${painted ? "visibility:hidden" : "display:none"}!important}` +
    `[data-kbd-spelling=${shown}]{visibility:visible!important}`;
  document.head.appendChild(style);
}

// True only for server HTML and hydration, where the script runs as parsed.
const subscribe = () => () => {};
const useServerHtml = () =>
  useSyncExternalStore(
    subscribe,
    () => false,
    () => true,
  );

type KbdProps = Omit<ComponentProps<"kbd">, "children"> & {
  /** Keys pressed together, in order: `["mod", "K"]`. `mod` is ⌘ on Apple, Ctrl elsewhere. */
  keys: string[];
  /** `caps` (default) draws each key as a cap; `plain` is text only, like "⌘K" or "Ctrl+K". */
  variant?: "caps" | "plain";
  size?: "sm" | "md";
  /** Force one platform's spelling. */
  platform?: Platform;
};

/** A key or shortcut as the reader's keyboard labels it: ⌘K on Apple, Ctrl K elsewhere. */
export function Kbd({ keys, variant = "caps", size = "md", platform, className, ...props }: KbdProps) {
  const serverHtml = useServerHtml();

  const spell = (p: Platform) => {
    const parts = keys.map((k) => key(k, p));
    return {
      look: variant === "caps" ? parts.map(([shown]) => shown) : [parts.map(([shown]) => shown).join(p === "apple" ? "" : "+")],
      read: parts.map(([, read]) => read).join(" "),
    };
  };
  const apple = spell("apple");
  const other = spell("other");
  const same = apple.read === other.read && apple.look.join("\n") === other.look.join("\n");
  const both = !platform && !same;

  // Symbols like ⌘ are read inconsistently, so screen readers get key names instead.
  const spelling = ({ look, read }: ReturnType<typeof spell>, p?: Platform) => (
    <span key={p} className={styles.spelling} data-kbd-spelling={p}>
      <span className={styles.keys} aria-hidden="true">
        {variant === "caps"
          ? look.map((shown, i) => (
              <kbd key={i} className={styles.key}>
                {shown}
              </kbd>
            ))
          : look[0]}
      </span>
      <span className={styles.srOnly}>{read}</span>
    </span>
  );

  return (
    <>
      {both && serverHtml && <script dangerouslySetInnerHTML={{ __html: SCRIPT }} suppressHydrationWarning />}
      <kbd
        className={className ? `${styles.root} ${className}` : styles.root}
        data-variant={variant}
        data-size={size}
        {...props}
      >
        {both ? [spelling(apple, "apple"), spelling(other, "other")] : spelling(platform === "apple" ? apple : other)}
      </kbd>
    </>
  );
}

@layer theme, base, components, utilities;

.tipLabel {
  composes: wrap from "../text/text.module.css";
}

@layer components {
  /* A sunken capsule track; items are icon capsules inside it, --nav-rail-pad
     from every edge, so their round ends are concentric with the track's. */
  .rail {
    --nav-rail-item-h: var(--ui-control-md);
    --nav-rail-item-w: calc(var(--nav-rail-item-h) * var(--ui-capsule));
    --nav-rail-pad: 4px;
    --nav-rail-gap: 4px;
    /* Opaque, the same as --ui-fill over the canvas, so a badge can cut out of it. */
    --nav-rail-bg: color-mix(in oklch, var(--ui-foreground) 4.5%, var(--ui-canvas));
    --nav-rail-capsule: light-dark(var(--ui-surface), color-mix(in oklch, var(--ui-surface), white 8%));
    --ui-icon-stroke: var(--ui-icon-stroke-medium);

    display: inline-flex;
    flex-direction: column;
    align-items: center;
    /* One spacing everywhere: the track's padding, the gap between items and
       the gap before the footer are all equal. */
    gap: var(--nav-rail-gap);
    box-sizing: border-box;
    padding: var(--nav-rail-pad);
    border-radius: calc(var(--nav-rail-item-h) / 2 + var(--nav-rail-pad));
    background: var(--nav-rail-bg);
    box-shadow: var(--ui-track-edge);
    font-family: var(--ui-font-sans);
  }

  .rail[data-orientation="horizontal"] {
    /* Its items at their capsule width, side by side: the width the bar takes
       when it has room (the component sets the counts). */
    --nav-rail-fit: calc(
      var(--nav-rail-count, 5) * var(--nav-rail-item-w) + (var(--nav-rail-count, 5) - 1) * var(--nav-rail-gap) + 2 *
        var(--nav-rail-pad)
    );
    /* Below this container width the bar is a phone's tab bar: it spans the
       width and shares it evenly between the items. */
    --nav-rail-phone: 480px;

    display: flex;
    flex-direction: row;
    /* In a container wider than a phone, the bar is as wide as its items and
       no wider: centered, it reads as one object, not a strip of spread-out
       icons. In a phone-width one, the second term (a container condition
       without a query, since the bar can't query its own parent) is larger
       than the container, so the bar fills it. Either way it never passes
       its container: the items give way evenly instead. */
    width: 100%;
    max-width: max(var(--nav-rail-fit), calc(100% - (100% - var(--nav-rail-phone)) * 1000));
    margin-inline: auto;
  }

  /* A phone's bottom bar: pinned to the bottom, floating clear of the home
     indicator (env() is 0 where there's none). --nav-rail-safe-bottom lets a
     frame that draws its own indicator stand in for the device's. */
  .rail[data-orientation="horizontal"][data-fixed] {
    position: fixed;
    inset-inline: 0;
    bottom: max(var(--ui-space-2), var(--nav-rail-safe-bottom, env(safe-area-inset-bottom, 0px)));
    z-index: 40;
    width: calc(100% - 2 * var(--ui-space-2));
  }

  .track {
    position: relative;
    isolation: isolate;
  }

  /* The list and the footer split the width so every item gets the same
     share: the list's basis is its gaps, its weight its item count. */
  .rail[data-orientation="horizontal"] .track {
    flex: var(--nav-rail-items, 4) 1 calc((var(--nav-rail-items, 4) - 1) * var(--nav-rail-gap));
    min-width: 0;
  }

  .list {
    display: flex;
    flex-direction: column;
    gap: var(--nav-rail-gap);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .rail[data-orientation="horizontal"] .list {
    flex-direction: row;
  }

  .cell {
    display: flex;
  }

  .rail[data-orientation="horizontal"] .cell {
    /* Equal shares of the bar: at their capsule width when it has room,
       wider on a phone, and evenly narrower rather than past its edge. */
    flex: 1 1 0;
    min-width: 0;
    justify-content: center;
  }

  /* The rail's far end: the footer is pushed there when the rail is stretched. */
  .footer {
    display: flex;
    margin-block-start: auto;
  }

  .rail[data-orientation="horizontal"] .footer {
    flex: 1 1 0;
    min-width: 0;
    margin-block-start: 0;
  }

  .rail[data-orientation="horizontal"] .footer > .item {
    width: 100%;
  }

  /* The raised capsule behind the current item; it glides from item to item. */
  .indicator {
    position: absolute;
    top: 0;
    left: 0;
    z-index: -1;
    border-radius: var(--ui-radius-full);
    background: var(--nav-rail-capsule);
    box-shadow:
      0 0 0 var(--ui-hairline) var(--ui-border-strong),
      var(--ui-shadow-control);
    contain: layout style size;
    pointer-events: none;
    visibility: hidden;
  }

  .track[data-ready] .indicator[data-visible] {
    visibility: visible;
  }

  .item {
    position: relative;
    display: grid;
    place-items: center;
    box-sizing: border-box;
    width: var(--nav-rail-item-w);
    height: var(--nav-rail-item-h);
    padding: 0;
    border: 0;
    border-radius: var(--ui-radius-full);
    background: transparent;
    color: var(--ui-muted);
    font: inherit;
    text-decoration: none;
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .rail[data-orientation="horizontal"] .cell .item {
    width: 100%;
  }

  .item[data-current] {
    color: var(--ui-foreground);
  }

  /* Before the capsule is measured, the current item paints its own. */
  .track:not([data-ready]) .item[data-current] {
    background: var(--nav-rail-capsule);
    box-shadow:
      0 0 0 var(--ui-hairline) var(--ui-border-strong),
      var(--ui-shadow-control);
  }

  /* Hover only brings the icon up to the text color: no fill. The tooltip
     already says which item the pointer is on. */
  @media (hover: hover) {
    .item:hover:not([data-current]) {
      color: var(--ui-foreground);
    }
  }

  .item:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .icon {
    display: grid;
    place-items: center;
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
  }

  .icon > svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
  }

  /* An unread count at the icon's top right. It grows away from the icon, and a
     ring of whatever is behind it cuts it out of the glyph. */
  .badge {
    position: absolute;
    top: 4px;
    left: calc(50% + 2px);
    display: grid;
    place-items: center;
    box-sizing: border-box;
    min-width: 18px;
    height: 18px;
    padding-inline: 5px;
    border-radius: var(--ui-radius-full);
    background: var(--ui-accent);
    box-shadow: 0 0 0 var(--ui-knockout) var(--nav-rail-bg);
    color: var(--ui-on-accent);
    font: var(--ui-weight-medium) var(--ui-text-sm) / 1 var(--ui-font-sans);
    font-variant-numeric: tabular-nums;
    pointer-events: none;
    transition: box-shadow var(--ui-dur-instant) var(--ui-ease-color);
  }

  .item[data-current] .badge {
    box-shadow: 0 0 0 var(--ui-knockout) var(--nav-rail-capsule);
  }

  /* The hit area spans half the gap on each side, so a pointer moving down the
     rail goes straight from one item to the next and the tooltip never closes
     between them. */
  .item::before {
    content: "";
    position: absolute;
    inset: calc(var(--nav-rail-gap) / -2) 0;
  }

  .rail[data-orientation="horizontal"] .item::before {
    inset: 0 calc(var(--nav-rail-gap) / -2);
  }

  @media (pointer: coarse) {
    .item::after {
      content: "";
      position: absolute;
      inset: -2px;
    }
    /* On a bottom bar a finger lands anywhere on the bar: each item's hit
       area runs to the bar's edges and halfway to its neighbors, 48px tall. */
    .rail[data-orientation="horizontal"] .item::after {
      inset: calc(var(--nav-rail-pad) * -1) calc(var(--nav-rail-gap) / -2);
    }
  }

  /* A long press shows the tooltip and sliding along the rail moves it, so the
     browser keeps only the scroll across the rail, and no callout menu. */
  .rail[data-orientation="vertical"] .item {
    touch-action: pan-x;
    -webkit-touch-callout: none;
  }

  .rail[data-orientation="horizontal"] .item {
    touch-action: pan-y;
    -webkit-touch-callout: none;
  }

  /* The shared tooltip. Base UI places the positioner; once it's on screen it
     glides to each new item, and the popup's width eases to the new label. */
  .positioner {
    z-index: 60;
    /* While it resizes, Base UI lifts the popup out of flow; these keep the box. */
    width: var(--positioner-width);
    height: var(--positioner-height);
    max-width: var(--available-width);
  }

  .positioner[data-glide] {
    transition:
      top var(--ui-dur-glide) var(--ui-ease-glide),
      left var(--ui-dur-glide) var(--ui-ease-glide),
      right var(--ui-dur-glide) var(--ui-ease-glide),
      bottom var(--ui-dur-glide) var(--ui-ease-glide),
      transform var(--ui-dur-glide) var(--ui-ease-glide);
  }

  .tooltip {
    position: relative;
    box-sizing: border-box;
    width: var(--popup-width, auto);
    height: var(--popup-height, auto);
    max-width: min(280px, calc(100vw - 16px));
    overflow: clip;
    border-radius: var(--ui-radius-sm);
    background: var(--ui-ink);
    box-shadow: var(--ui-shadow-raised);
    color: var(--ui-on-ink);
    font: var(--ui-weight-medium) var(--ui-text-sm) / var(--ui-leading-sm) var(--ui-font-sans);
    transform-origin: var(--transform-origin);
    opacity: 1;
    scale: 1;
    filter: none;
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter),
      scale var(--ui-dur-fast) var(--ui-ease-enter),
      filter var(--ui-dur-fast) var(--ui-ease-enter);
  }

  .positioner[data-glide] .tooltip {
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter),
      scale var(--ui-dur-fast) var(--ui-ease-enter),
      filter var(--ui-dur-fast) var(--ui-ease-enter),
      width var(--ui-dur-glide) var(--ui-ease-glide),
      height var(--ui-dur-glide) var(--ui-ease-glide);
  }

  .tooltip[data-starting-style],
  .tooltip[data-ending-style] {
    opacity: 0;
    scale: 0.97;
    filter: blur(2px);
  }

  .tooltip[data-ending-style] {
    transition:
      opacity var(--ui-dur-instant) var(--ui-ease-exit),
      scale var(--ui-dur-instant) var(--ui-ease-exit),
      filter var(--ui-dur-instant) var(--ui-ease-exit);
  }

  /* Warm (back within 300ms) or opened by focus: it's simply there. */
  .tooltip[data-instant]:is([data-starting-style], [data-ending-style]) {
    transition-duration: 0s;
  }

  .viewport {
    position: relative;
    padding: var(--ui-space-1) var(--ui-space-2);
  }

  .viewport > [data-previous] {
    top: var(--ui-space-1);
    left: var(--ui-space-2);
  }

  /* The label crossfades, offset half a beat, and rolls a few px the way the tooltip travelled. */
  .viewport > [data-current] {
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter) 60ms,
      translate var(--ui-dur-glide) var(--ui-ease-glide);
  }

  .viewport > [data-previous] {
    transition:
      opacity var(--ui-dur-instant) var(--ui-ease-color),
      translate var(--ui-dur-glide) var(--ui-ease-glide);
  }

  .viewport > [data-current][data-starting-style],
  .viewport > [data-previous][data-ending-style] {
    opacity: 0;
  }

  .viewport[data-activation-direction~="down"] > [data-current][data-starting-style],
  .viewport[data-activation-direction~="up"] > [data-previous][data-ending-style] {
    translate: 0 4px;
  }

  .viewport[data-activation-direction~="up"] > [data-current][data-starting-style],
  .viewport[data-activation-direction~="down"] > [data-previous][data-ending-style] {
    translate: 0 -4px;
  }

  .viewport[data-activation-direction~="right"] > [data-current][data-starting-style],
  .viewport[data-activation-direction~="left"] > [data-previous][data-ending-style] {
    translate: 4px 0;
  }

  .viewport[data-activation-direction~="left"] > [data-current][data-starting-style],
  .viewport[data-activation-direction~="right"] > [data-previous][data-ending-style] {
    translate: -4px 0;
  }

  .tip {
    display: flex;
    align-items: baseline;
    gap: var(--ui-space-2);
  }

  .tipLabel {
    min-width: 0;
  }

  /* No keyboard, no shortcut: a long press on a phone shows only the name. */
  @media (hover: none) {
    .tip .tipKbd {
      display: none;
    }
  }

  .tipKbd {
    flex-shrink: 0;
    color: var(--ui-on-ink-muted);
    line-height: var(--ui-leading-sm);
  }

  @media (prefers-reduced-motion: reduce) {
    .positioner[data-glide],
    .positioner[data-glide] .tooltip {
      transition: opacity var(--ui-dur-fast) var(--ui-ease-enter);
    }
    .tooltip[data-starting-style],
    .tooltip[data-ending-style] {
      scale: none;
      filter: none;
    }
    .viewport > [data-current],
    .viewport > [data-previous] {
      translate: none !important;
    }
  }

  @media (forced-colors: active) {
    .item[data-current] {
      outline: 1px solid CanvasText;
      outline-offset: -1px;
    }
    .tooltip {
      border: 1px solid CanvasText;
    }
  }
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type CSSProperties,
  type HTMLAttributes,
  type KeyboardEvent,
  type PointerEvent,
  type ReactElement,
  type ReactNode,
  type Ref,
} from "react";
import { Tooltip as BaseTooltip } from "@base-ui/react/tooltip";
import { Kbd } from "../kbd/kbd";
import styles from "./nav-rail.module.css";

/** Hover delay before the rail's tooltip first opens; the same as Tooltip's. */
const OPEN_DELAY = 500;
/** After the tooltip closes, coming back to the rail opens it instantly for this long. */
const WARM_WINDOW = 300;
/** On touch, holding an item this long shows its tooltip, the way a long press does on a phone. */
const LONG_PRESS = 400;

export type NavRailItem = {
  id: string;
  /** The item's name: its accessible name and the tooltip's text. */
  label: string;
  /** A 16px icon, drawn in `currentColor`. */
  icon: ReactNode;
  /** One key pressed with ⌘ or Ctrl, like `"1"`. Shown in the tooltip; handled when `shortcuts` is on. */
  shortcut?: string;
  /** Renders a link instead of a button. */
  href?: string;
  /** An unread count on the icon. 0 or undefined hides it. */
  badge?: number;
};

type Payload = { label: string; shortcut?: string };

type RailContext = {
  handle: ReturnType<typeof BaseTooltip.createHandle<Payload>>;
  orientation: "vertical" | "horizontal";
  /** Where the tooltip portals: the nearest open dialog or themed section, so it takes that theme. */
  container: HTMLElement | null;
  /** The rail item look `NavRailTrigger` gives its child; none in a tooltip group. */
  itemClass?: string;
};

const Context = createContext<RailContext | null>(null);

type NavRailProps = Omit<ComponentProps<"nav">, "children" | "onChange"> & {
  /** Names the landmark: "Main". */
  "aria-label"?: string;
  items: NavRailItem[];
  /** The id of the current item. */
  value?: string;
  /** Called with an item's id when it's pressed, or its shortcut is. */
  onValueChange?: (id: string) => void;
  /** Pinned to the far end: an account button, usually. Wrap it in `NavRailTrigger` to give it the tooltip. */
  footer?: ReactNode;
  /** `vertical` (default): a side rail. `horizontal`: a bottom bar; the tooltip opens above. */
  orientation?: "vertical" | "horizontal";
  /** Handle ⌘ or Ctrl plus each item's `shortcut` anywhere on the page. */
  shortcuts?: boolean;
  /** Horizontal only: pin the bar to the bottom of the viewport (or of the nearest transformed or
   * `contain: layout` ancestor), floating clear of the phone's home indicator. */
  fixed?: boolean;
};

function token(el: Element, name: string, fallback: string) {
  return getComputedStyle(el).getPropertyValue(name).trim() || fallback;
}

function ms(value: string) {
  return value.endsWith("ms") ? parseFloat(value) : parseFloat(value) * 1000;
}

/** A compact app navigation rail: icon items, one shared tooltip that glides between them, and a capsule on the current one. */
export function NavRail({
  "aria-label": ariaLabel = "Main",
  items,
  value,
  onValueChange,
  footer,
  orientation = "vertical",
  shortcuts = false,
  fixed = false,
  className,
  style,
  ...props
}: NavRailProps) {
  const [handle] = useState(() => BaseTooltip.createHandle<Payload>());
  const [navEl, setNavEl] = useState<HTMLElement | null>(null);
  const container = navEl?.closest<HTMLElement>("dialog[open], [data-theme]") ?? null;
  const listRef = useRef<HTMLDivElement>(null);
  const indicatorRef = useRef<HTMLSpanElement>(null);
  const placed = useRef<{ value: string; x: number; y: number } | null>(null);
  const vertical = orientation === "vertical";

  // Glide the capsule to the current item, like the segmented control's pill.
  const place = useCallback(
    (animate: boolean) => {
      const list = listRef.current;
      const indicator = indicatorRef.current;
      if (!list || !indicator) return;
      const item = value ? list.querySelector<HTMLElement>(`[data-id="${CSS.escape(value)}"]`) : null;
      if (!item || !value) {
        indicator.removeAttribute("data-visible");
        placed.current = null;
        return;
      }
      const box = item.getBoundingClientRect();
      const origin = list.getBoundingClientRect();
      const x = box.left - origin.left;
      const y = box.top - origin.top;
      const last = placed.current;
      indicator.setAttribute("data-visible", "");
      indicator.style.width = `${box.width}px`;
      indicator.style.height = `${box.height}px`;
      if (last && last.value === value && last.x === x && last.y === y) return;

      let from = last ? `translate(${last.x}px, ${last.y}px)` : null;
      const running = indicator.getAnimations();
      if (running.length) {
        from = getComputedStyle(indicator).transform;
        running.forEach((a) => a.cancel());
      }
      const to = `translate(${x}px, ${y}px)`;
      indicator.style.transform = to;
      placed.current = { value, x, y };

      const moved = last && last.value !== value;
      if (!animate || !moved || !from || matchMedia("(prefers-reduced-motion: reduce)").matches) return;
      indicator.animate([{ transform: from }, { transform: to }], {
        duration: ms(token(list, "--ui-dur-glide", "320ms")),
        easing: token(list, "--ui-ease-glide", "ease-out"),
      });
    },
    [value],
  );

  useLayoutEffect(() => {
    place(true);
    listRef.current?.setAttribute("data-ready", "");
  }, [place, orientation]);

  useEffect(() => {
    const list = listRef.current;
    if (!list) return;
    let frame = 0;
    const remeasure = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => place(false));
    };
    const observer = new ResizeObserver(remeasure);
    observer.observe(list);
    for (const item of list.querySelectorAll("[data-id]")) observer.observe(item);
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
    };
  }, [place, items.length]);

  // ⌘ or Ctrl plus a shortcut presses that item, so a link navigates and a button selects.
  useEffect(() => {
    if (!shortcuts) return;
    const onKey = (e: globalThis.KeyboardEvent) => {
      if (e.defaultPrevented || e.altKey || e.shiftKey || !(e.metaKey || e.ctrlKey)) return;
      const digit = /^Digit(\d)$/.exec(e.code)?.[1];
      const item = items.find(
        (i) => i.shortcut && (i.shortcut.toLowerCase() === e.key.toLowerCase() || i.shortcut === digit),
      );
      if (!item) return;
      e.preventDefault();
      listRef.current?.querySelector<HTMLElement>(`[data-id="${CSS.escape(item.id)}"]`)?.click();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [shortcuts, items]);

  // Touch has no hover, so a long press shows the tooltip instead. Sliding the
  // finger along the rail glides it from item to item, and lifting it presses
  // the item under the finger, like a phone's tab bar. A short tap is a tap.
  const press = useRef<{ id: number; timer: number; x: number; y: number; over: HTMLElement | null; held: boolean } | null>(
    null,
  );
  const swallowClick = useRef(false);
  useEffect(() => () => window.clearTimeout(press.current?.timer), []);

  function itemAt(x: number, y: number) {
    const hit = document.elementFromPoint(x, y)?.closest<HTMLElement>("[data-rail-item]");
    return hit && navEl?.contains(hit) ? hit : null;
  }

  function endPress(select: boolean) {
    const p = press.current;
    if (!p) return;
    window.clearTimeout(p.timer);
    press.current = null;
    if (!p.held) return;
    handle.close();
    // The browser may still send a click to where the finger went down; the
    // press is ours now, so it lands on the item under the finger instead.
    swallowClick.current = true;
    window.setTimeout(() => (swallowClick.current = false), 400);
    if (select && p.over) {
      swallowClick.current = false;
      p.over.click();
      swallowClick.current = true;
    }
  }

  function onPointerDown(e: PointerEvent<HTMLElement>) {
    if (e.pointerType !== "touch" || press.current) return;
    const item = (e.target as Element).closest<HTMLElement>("[data-rail-item]");
    if (!item) return;
    const p = { id: e.pointerId, x: e.clientX, y: e.clientY, over: item, held: false, timer: 0 };
    p.timer = window.setTimeout(() => {
      p.held = true;
      if (p.over?.id) handle.open(p.over.id);
    }, LONG_PRESS);
    press.current = p;
  }

  function onPointerMove(e: PointerEvent<HTMLElement>) {
    const p = press.current;
    if (!p || p.id !== e.pointerId) return;
    if (!p.held) {
      // Moving before the tooltip shows is a scroll or a swipe, not a press.
      if (Math.hypot(e.clientX - p.x, e.clientY - p.y) > 8) endPress(false);
      return;
    }
    const over = itemAt(e.clientX, e.clientY);
    if (over !== p.over) {
      p.over = over;
      if (over?.id) handle.open(over.id);
      else handle.close();
    }
  }

  // Arrow keys along the rail, Home and End; Tab still visits every item.
  function onKeyDown(e: KeyboardEvent<HTMLElement>) {
    const prev = vertical ? "ArrowUp" : "ArrowLeft";
    const next = vertical ? "ArrowDown" : "ArrowRight";
    if (![prev, next, "Home", "End"].includes(e.key)) return;
    const all = [...e.currentTarget.querySelectorAll<HTMLElement>("[data-rail-item]")];
    const at = all.indexOf(document.activeElement as HTMLElement);
    if (at === -1) return;
    e.preventDefault();
    const to =
      e.key === "Home"
        ? 0
        : e.key === "End"
          ? all.length - 1
          : (at + (e.key === next ? 1 : -1) + all.length) % all.length;
    all[to]?.focus();
  }

  return (
    <Context.Provider value={{ handle, orientation, container, itemClass: styles.item }}>
      <BaseTooltip.Provider delay={OPEN_DELAY} timeout={WARM_WINDOW}>
        <nav
          ref={setNavEl}
          aria-label={ariaLabel}
          data-orientation={orientation}
          data-fixed={(fixed && !vertical) || undefined}
          className={className ? `${styles.rail} ${className}` : styles.rail}
          // How many items share a bottom bar's width, so CSS can size it to fit them.
          style={
            {
              "--nav-rail-items": items.length,
              "--nav-rail-count": items.length + (footer ? 1 : 0),
              ...style,
            } as CSSProperties
          }
          onKeyDown={onKeyDown}
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={(e) => press.current?.id === e.pointerId && endPress(true)}
          onPointerCancel={(e) => press.current?.id === e.pointerId && endPress(false)}
          onClickCapture={(e) => {
            if (!swallowClick.current) return;
            swallowClick.current = false;
            e.preventDefault();
            e.stopPropagation();
          }}
          // A long press on a link would otherwise open the browser's menu over the tooltip.
          onContextMenu={(e) => press.current && e.preventDefault()}
          {...props}
        >
          <div ref={listRef} className={styles.track}>
            <span ref={indicatorRef} className={styles.indicator} aria-hidden="true" />
            <ul className={styles.list}>
              {items.map((item) => {
                const current = item.id === value;
                const count = item.badge && item.badge > 0 ? item.badge : 0;
                const name = count ? `${item.label}, ${count} new` : item.label;
                const element = item.href ? <a href={item.href} /> : <button type="button" />;
                return (
                  <li key={item.id} className={styles.cell}>
                    <BaseTooltip.Trigger
                      handle={handle}
                      payload={{ label: item.label, shortcut: item.shortcut }}
                      delay={OPEN_DELAY}
                      render={element}
                      data-id={item.id}
                      data-rail-item=""
                      data-current={current || undefined}
                      aria-label={name}
                      aria-current={current ? "page" : undefined}
                      aria-keyshortcuts={
                        shortcuts && item.shortcut ? `Meta+${item.shortcut} Control+${item.shortcut}` : undefined
                      }
                      className={styles.item}
                      onClick={() => onValueChange?.(item.id)}
                    >
                      <span className={styles.icon} aria-hidden="true">
                        {item.icon}
                      </span>
                      {count > 0 && (
                        <span className={styles.badge} aria-hidden="true">
                          {count > 99 ? "99+" : count}
                        </span>
                      )}
                    </BaseTooltip.Trigger>
                  </li>
                );
              })}
            </ul>
          </div>
          {footer && <div className={styles.footer}>{footer}</div>}
        </nav>
        <RailTooltip />
      </BaseTooltip.Provider>
    </Context.Provider>
  );
}

/** The one tooltip every item shares. */
function RailTooltip() {
  const rail = useContext(Context)!;
  // Position and width glide only once it's on screen, so it never slides in from the corner.
  const [gliding, setGliding] = useState(false);
  const open = useRef(false);
  const frame = useRef(0);
  useEffect(() => () => cancelAnimationFrame(frame.current), []);

  return (
    <BaseTooltip.Root
      handle={rail.handle}
      onOpenChange={(next) => {
        open.current = next;
        cancelAnimationFrame(frame.current);
        // Two frames: placed, then painted where it belongs. Already gliding means
        // it never left: the pointer crossed a gap and came back while it faded.
        if (next)
          frame.current = requestAnimationFrame(() => {
            frame.current = requestAnimationFrame(() => setGliding(true));
          });
      }}
      // Stop gliding only once it's gone. Crossing the gap between two items
      // closes it for a moment; dropping the glide then made it jump to the next
      // item instead of gliding, whenever the pointer happened to land in the gap.
      onOpenChangeComplete={(done) => {
        if (!done && !open.current) setGliding(false);
      }}
    >
      {({ payload }) => (
        <BaseTooltip.Portal container={rail.container ?? undefined}>
          <BaseTooltip.Positioner
            className={styles.positioner}
            side={rail.orientation === "vertical" ? "inline-end" : "top"}
            sideOffset={8}
            collisionPadding={8}
            data-glide={gliding || undefined}
          >
            {/* The items carry the names; this is a visual echo of them. */}
            <BaseTooltip.Popup className={styles.tooltip} aria-hidden="true">
              <BaseTooltip.Viewport className={styles.viewport}>
                {payload && (
                  <span className={styles.tip}>
                    <span className={styles.tipLabel}>{payload.label}</span>
                    {payload.shortcut && (
                      <Kbd className={styles.tipKbd} keys={["mod", payload.shortcut]} variant="plain" size="sm" />
                    )}
                  </span>
                )}
              </BaseTooltip.Viewport>
            </BaseTooltip.Popup>
          </BaseTooltip.Positioner>
        </BaseTooltip.Portal>
      )}
    </BaseTooltip.Root>
  );
}

type NavRailTooltipGroupProps = {
  /** An element inside the group: the tooltip portals into its nearest open dialog or themed section. */
  root?: HTMLElement | null;
  /** `vertical` (default): the tooltip opens beside the triggers; `horizontal`: above them. */
  orientation?: "vertical" | "horizontal";
  children: ReactNode;
};

/**
 * The rail's one gliding tooltip, for triggers that aren't in a `NavRail`:
 * a collapsed sidebar's icons, a toolbar. Wrap each trigger in `NavRailTrigger`.
 */
export function NavRailTooltipGroup({ root = null, orientation = "vertical", children }: NavRailTooltipGroupProps) {
  const [handle] = useState(() => BaseTooltip.createHandle<Payload>());
  const container = root?.closest<HTMLElement>("dialog[open], [data-theme]") ?? null;
  return (
    <Context.Provider value={{ handle, orientation, container }}>
      <BaseTooltip.Provider delay={OPEN_DELAY} timeout={WARM_WINDOW}>
        {children}
        <RailTooltip />
      </BaseTooltip.Provider>
    </Context.Provider>
  );
}

type NavRailTriggerProps = Omit<HTMLAttributes<HTMLElement>, "children"> & {
  /** What the tooltip says; give the child the same accessible name. */
  label: string;
  shortcut?: string;
  /** Keep the tooltip closed, as while a sidebar shows its labels. */
  disabled?: boolean;
  ref?: Ref<HTMLButtonElement>;
  /** One focusable element, like the account button in `footer`. */
  children: ReactElement;
};

/**
 * Joins a control to the rail's shared tooltip. In a `NavRail` it's styled as a
 * rail item; in a `NavRailTooltipGroup` it keeps its own look. Other props pass
 * through to the child, so a menu can render it as its trigger.
 */
export function NavRailTrigger({ label, shortcut, disabled = false, children, ...props }: NavRailTriggerProps) {
  const rail = useContext(Context);
  if (!rail) return children;
  return (
    <BaseTooltip.Trigger
      {...props}
      handle={rail.handle}
      payload={{ label, shortcut }}
      delay={OPEN_DELAY}
      disabled={disabled}
      render={children}
      data-rail-item=""
      className={rail.itemClass}
    />
  );
}

@layer theme, base, components, utilities;

/* Registered so the edge alphas can transition. */
@property --scroll-area-start {
  syntax: "<number>";
  inherits: false;
  initial-value: 1;
}

@property --scroll-area-end {
  syntax: "<number>";
  inherits: false;
  initial-value: 1;
}

@layer components {
  /* The focus ring lives here because the viewport's mask would fade it out. */
  .root {
    position: relative;
    display: flex;
    flex-direction: column;
    min-width: 0;
    min-height: 0;
  }

  .root:has(> .viewport:focus-visible) {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .viewport {
    --scroll-area-fade: var(--ui-space-6, 32px);
    flex: 1 1 auto;
    min-width: 0;
    min-height: 0;
    border-radius: inherit;
    outline: none;
    scrollbar-width: thin;
    scrollbar-color: var(--ui-border-strong) transparent;
  }

  .viewport[data-orientation="vertical"] {
    overflow-x: hidden;
    overflow-y: auto;
    scroll-padding-block: var(--scroll-area-fade);
  }

  /* Stops a sideways swipe at the end from triggering browser back. */
  .viewport[data-orientation="horizontal"] {
    overflow-x: auto;
    overflow-y: hidden;
    overscroll-behavior-inline: contain;
    scroll-padding-inline: var(--scroll-area-fade);
  }

  /* One fade layer over the whole viewport, scrollbar included: a solid
     strip kept for a classic scrollbar also left a sliver of each row at full
     opacity beside it. */
  .viewport[data-fade] {
    mask-image: linear-gradient(
      var(--scroll-area-direction, to bottom),
      rgb(0 0 0 / var(--scroll-area-start, 1)),
      black var(--scroll-area-fade, 32px),
      black calc(100% - var(--scroll-area-fade, 32px)),
      rgb(0 0 0 / var(--scroll-area-end, 1))
    );
  }

  .viewport[data-fade][data-orientation="horizontal"] {
    --scroll-area-direction: to right;
  }

  :is([dir="rtl"]) .viewport[data-fade][data-orientation="horizontal"] {
    --scroll-area-direction: to left;
  }

  @supports (animation-timeline: scroll()) {
    .viewport[data-fade] {
      animation:
        scroll-area-start linear both,
        scroll-area-end linear both;
      animation-timeline: scroll(self block), scroll(self block);
      animation-range:
        0 var(--scroll-area-fade),
        calc(100% - var(--scroll-area-fade)) 100%;
    }

    .viewport[data-fade][data-orientation="horizontal"] {
      animation-timeline: scroll(self inline), scroll(self inline);
    }

    /* Chromium keeps an animation's last value once its timeline goes inactive;
       the script sets data-fits so stale fades clear. */
    .viewport[data-fade][data-fits] {
      animation: none;
    }
  }

  @keyframes scroll-area-start {
    from {
      --scroll-area-start: 1;
    }
    to {
      --scroll-area-start: 0;
    }
  }

  @keyframes scroll-area-end {
    from {
      --scroll-area-end: 0;
    }
    to {
      --scroll-area-end: 1;
    }
  }

  /* Script fallback; data-ready skips the transition on first paint. */
  @supports not (animation-timeline: scroll()) {
    .viewport[data-fade][data-ready] {
      transition:
        --scroll-area-start var(--ui-dur-fast) var(--ui-ease-color),
        --scroll-area-end var(--ui-dur-fast) var(--ui-ease-color);
    }
  }

  .content {
    display: flow-root;
  }

  .viewport[data-orientation="horizontal"] > .content {
    width: max-content;
    min-width: 100%;
  }
}

"use client";

import { useLayoutEffect, useRef, useState, type ComponentProps, type Ref } from "react";
import styles from "./scroll-area.module.css";

type ScrollAreaProps = Omit<ComponentProps<"div">, "ref"> & {
  /** Accessible name; makes the area a named region. */
  label?: string;
  orientation?: "vertical" | "horizontal";
  /** Fade edges that have more content past them. */
  fade?: boolean;
  /** The scrolling element. */
  ref?: Ref<HTMLDivElement>;
};

const FOCUSABLE =
  'a[href], area[href], button:not([disabled]), input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), iframe, summary, [contenteditable]:not([contenteditable="false"]), [tabindex]:not([tabindex="-1"])';

/** A scroll container whose edges fade where there's more content past them. */
export function ScrollArea({
  label,
  orientation = "vertical",
  fade = true,
  className,
  style,
  children,
  ref,
  "aria-labelledby": labelledBy,
  ...props
}: ScrollAreaProps) {
  const viewportRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  // Keyboard users need a tab stop to scroll, but only when nothing inside is focusable.
  const [tabStop, setTabStop] = useState(false);

  useLayoutEffect(() => {
    const viewport = viewportRef.current;
    const content = contentRef.current;
    if (!viewport || !content) return;
    const vertical = orientation === "vertical";
    const cssFades = typeof CSS !== "undefined" && CSS.supports("animation-timeline: scroll()");
    let frame = 0;
    let ready = false;

    const measure = () => {
      const pos = Math.abs(vertical ? viewport.scrollTop : viewport.scrollLeft);
      const max = vertical
        ? viewport.scrollHeight - viewport.clientHeight
        : viewport.scrollWidth - viewport.clientWidth;
      viewport.toggleAttribute("data-fits", max <= 1);
      if (!cssFades) {
        viewport.style.setProperty("--scroll-area-start", pos > 1 ? "0" : "1");
        viewport.style.setProperty("--scroll-area-end", pos < max - 1 ? "0" : "1");
      }
      const bar = vertical ? viewport.offsetWidth - viewport.clientWidth : viewport.offsetHeight - viewport.clientHeight;
      viewport.style.setProperty("--scroll-area-bar", `${Math.max(0, bar)}px`);
      setTabStop(max > 1 && content.querySelector(FOCUSABLE) === null);
      if (!ready) {
        ready = true;
        frame = requestAnimationFrame(() => {
          viewport.dataset.ready = "";
        });
      }
    };

    let pending = 0;
    const onScroll = () => {
      if (pending) return;
      pending = requestAnimationFrame(() => {
        pending = 0;
        measure();
      });
    };

    // Vertical wheel scrolls a horizontal row until it hits an end, then the page.
    const onWheel = (event: WheelEvent) => {
      if (vertical || event.ctrlKey || event.shiftKey) return;
      if (Math.abs(event.deltaY) <= Math.abs(event.deltaX)) return;
      const max = viewport.scrollWidth - viewport.clientWidth;
      if (max <= 1) return;
      const rtl = getComputedStyle(viewport).direction === "rtl";
      const step = event.deltaMode === 1 ? event.deltaY * 16 : event.deltaMode === 2 ? event.deltaY * viewport.clientWidth : event.deltaY;
      const pos = Math.abs(viewport.scrollLeft);
      const forward = step > 0;
      if ((forward && pos >= max - 1) || (!forward && pos <= 1)) return;
      event.preventDefault();
      viewport.scrollLeft += rtl ? -step : step;
    };

    measure();
    viewport.addEventListener("scroll", onScroll, { passive: true });
    viewport.addEventListener("wheel", onWheel, { passive: false });
    const resize = new ResizeObserver(measure);
    resize.observe(viewport);
    resize.observe(content);
    const mutation = new MutationObserver(measure);
    mutation.observe(content, { childList: true, subtree: true, attributes: true, attributeFilter: ["disabled", "tabindex", "href"] });

    return () => {
      cancelAnimationFrame(frame);
      cancelAnimationFrame(pending);
      viewport.removeEventListener("scroll", onScroll);
      viewport.removeEventListener("wheel", onWheel);
      resize.disconnect();
      mutation.disconnect();
      delete viewport.dataset.ready;
      viewport.removeAttribute("data-fits");
    };
  }, [orientation]);

  function setRefs(node: HTMLDivElement | null) {
    viewportRef.current = node;
    if (typeof ref === "function") ref(node);
    else if (ref) ref.current = node;
  }

  const named = Boolean(label || labelledBy);

  return (
    <div className={className ? `${styles.root} ${className}` : styles.root} style={style} data-orientation={orientation}>
      <div
        ref={setRefs}
        className={styles.viewport}
        data-orientation={orientation}
        data-fade={fade ? "" : undefined}
        role={named ? "region" : undefined}
        aria-label={label}
        aria-labelledby={labelledBy}
        tabIndex={tabStop ? 0 : undefined}
        {...props}
      >
        <div ref={contentRef} className={styles.content}>
          {children}
        </div>
      </div>
    </div>
  );
}

@layer theme, base, components, utilities;

/* Not inherited, so sizes never leak into nested skeletons. */
@property --skeleton-width {
  syntax: "*";
  inherits: false;
}

@property --skeleton-height {
  syntax: "*";
  inherits: false;
}

@property --skeleton-size {
  syntax: "*";
  inherits: false;
}

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  /* One element per bone, one background layer per bone. The sheen is a soft
     diagonal gradient fixed to the viewport (background-attachment: fixed) and
     every bone runs on one clock (syncSweep), so a single band of light crosses
     the whole layout and each bone lights up as it passes. The image is three
     viewports wide, so the band leaves the screen and rests between passes. */
  .bone {
    --skeleton-sheen: light-dark(
      color-mix(in oklch, var(--ui-surface) 62%, transparent),
      color-mix(in oklch, var(--ui-foreground) 9%, transparent)
    );

    display: block;
    max-width: 100%;
    background-color: var(--ui-fill-strong);
    /* Eased stops, so the band has no edges: light gathers and fades. */
    background-image: linear-gradient(
      110deg,
      transparent 42.5%,
      color-mix(in oklch, var(--skeleton-sheen) 22%, transparent) 45.5%,
      color-mix(in oklch, var(--skeleton-sheen) 62%, transparent) 48%,
      var(--skeleton-sheen) 50%,
      color-mix(in oklch, var(--skeleton-sheen) 62%, transparent) 52%,
      color-mix(in oklch, var(--skeleton-sheen) 22%, transparent) 54.5%,
      transparent 57.5%
    );
    background-size: 300% 100%;
    background-repeat: no-repeat;
    background-attachment: fixed;
    animation: skeleton-sweep calc(var(--ui-dur-sweep) * 2) linear infinite;
    pointer-events: none;
    user-select: none;
  }

  :is([dir="rtl"]) .bone {
    animation-direction: reverse;
  }

  @keyframes skeleton-sweep {
    from {
      background-position: 100% 0;
    }
    to {
      background-position: 0 0;
    }
  }

  .block {
    width: var(--skeleton-width, 100%);
    height: var(--skeleton-height, var(--ui-space-4));
    border-radius: var(--ui-radius-sm);
  }

  .block[data-radius="md"] {
    border-radius: var(--ui-radius-md);
  }

  .block[data-radius="lg"] {
    border-radius: var(--ui-radius-lg);
  }

  .block[data-radius="full"] {
    border-radius: var(--ui-radius-full);
  }

  .circle {
    flex-shrink: 0;
    width: var(--skeleton-size);
    height: var(--skeleton-size);
    border-radius: var(--ui-radius-full);
  }

  /* Text */

  .text {
    display: block;
    width: var(--skeleton-width, 100%);
    max-width: 100%;
  }

  .text[data-size="sm"] {
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
  }

  .text[data-size="md"] {
    font-size: var(--ui-text-md);
    line-height: var(--ui-leading-md);
  }

  .text[data-size="2xl"] {
    font-size: var(--ui-text-2xl);
    line-height: var(--ui-leading-2xl);
  }

  /* One inline bar per line, each the full width so the next one wraps. It's
     shorter than the line, so the strut sets the line height, as for text. */
  .bar {
    display: inline-block;
    vertical-align: baseline;
    width: 100%;
    height: 0.7em;
    height: 1cap;
    border-radius: var(--ui-radius-full);
  }

  .bar:last-child:not(:only-child) {
    width: var(--skeleton-last, 60%);
  }

  /* Group */

  .group {
    display: grid;
    min-width: 0;
  }

  .fallback,
  .content {
    grid-area: 1 / 1;
    min-width: 0;
  }

  .fallback {
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  .fallback[data-shown] {
    opacity: 1;
    transition: opacity var(--ui-dur-base) var(--ui-ease-enter);
  }

  .content[data-enter] {
    animation: skeleton-content-in var(--ui-dur-base) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2) backwards;
  }

  @keyframes skeleton-content-in {
    from {
      opacity: 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .bone {
      background-image: none;
      animation: none;
    }
  }

  /* Forced colors drop background fills; an outline keeps the shapes. */
  @media (forced-colors: active) {
    .bone {
      outline: var(--ui-hairline) solid GrayText;
      outline-offset: calc(var(--ui-hairline) * -1);
    }
  }
}

"use client";

import { useEffect, useState, type ComponentProps, type CSSProperties, type ReactNode } from "react";
import styles from "./skeleton.module.css";

type Length = number | string;

const css = (value: Length | undefined) => (typeof value === "number" ? `${value}px` : value);

/** Puts a late bone on the shared band's clock. */
function syncSweep(el: HTMLElement | null) {
  if (!el || typeof el.getAnimations !== "function") return;
  for (const animation of el.getAnimations()) animation.startTime = 0;
}

type SkeletonProps = Omit<ComponentProps<"span">, "children" | "ref"> & {
  /** Numbers are px. Defaults to full width. */
  width?: Length;
  /** Defaults to 16px. Numbers are px. */
  height?: Length;
  /** `sm` (default), `md`, `lg` or `full`. */
  radius?: "sm" | "md" | "lg" | "full";
};

/** A block standing in for something with a known size. */
export function Skeleton({ width, height, radius = "sm", className, style, ...props }: SkeletonProps) {
  return (
    <span
      ref={syncSweep}
      aria-hidden="true"
      data-radius={radius}
      className={className ? `${styles.bone} ${styles.block} ${className}` : `${styles.bone} ${styles.block}`}
      style={{ "--skeleton-width": css(width), "--skeleton-height": css(height), ...style } as CSSProperties}
      {...props}
    />
  );
}

type SkeletonCircleProps = Omit<ComponentProps<"span">, "children" | "ref"> & {
  /** Diameter. Defaults to 40px. */
  size?: Length;
};

/** A circle standing in for an avatar. */
export function SkeletonCircle({ size = 40, className, style, ...props }: SkeletonCircleProps) {
  return (
    <span
      ref={syncSweep}
      aria-hidden="true"
      className={className ? `${styles.bone} ${styles.circle} ${className}` : `${styles.bone} ${styles.circle}`}
      style={{ "--skeleton-size": css(size), ...style } as CSSProperties}
      {...props}
    />
  );
}

type SkeletonTextProps = Omit<ComponentProps<"span">, "children" | "ref"> & {
  lines?: number;
  /** Width of the whole block, e.g. `"9em"`. */
  width?: Length;
  /** Width of the last of several lines. Defaults to 60%. */
  lastLineWidth?: Length;
  /** Type step. Omit to inherit from the parent, the surest match. */
  size?: "sm" | "md" | "2xl";
};

/** Lines standing in for text, as tall as the real lines. */
export function SkeletonText({
  lines = 1,
  width,
  lastLineWidth = "60%",
  size,
  className,
  style,
  ...props
}: SkeletonTextProps) {
  const count = Number.isFinite(lines) ? Math.max(1, Math.round(lines)) : 1;
  return (
    <span
      aria-hidden="true"
      data-size={size}
      className={className ? `${styles.text} ${className}` : styles.text}
      style={{ "--skeleton-width": css(width), "--skeleton-last": css(lastLineWidth), ...style } as CSSProperties}
      {...props}
    >
      {Array.from({ length: count }, (_, i) => (
        <span key={i} ref={syncSweep} className={`${styles.bone} ${styles.bar}`} />
      ))}
    </span>
  );
}

/** True once `loading` has lasted `delay` ms. */
export function useLoadingDelay(loading: boolean, delay = 300) {
  const [late, setLate] = useState(false);
  useEffect(() => {
    if (!loading) return;
    const timer = window.setTimeout(() => setLate(true), delay);
    return () => {
      window.clearTimeout(timer);
      setLate(false);
    };
  }, [loading, delay]);
  return loading && late;
}

// Drops the skeleton anyway in case the entrance animation never runs.
const ENTER_BACKSTOP = 1000;

type SkeletonGroupProps = Omit<ComponentProps<"div">, "children"> & {
  /** While true the skeleton holds the place. */
  loading: boolean;
  fallback: ReactNode;
  children?: ReactNode;
  /** Announced once the wait passes `delay`. */
  label?: string;
  /** Ms before the skeleton shows. Defaults to 300. */
  delay?: number;
};

/** Holds the place of content that is on its way. */
export function SkeletonGroup({
  loading,
  fallback,
  children,
  label = "Loading…",
  delay = 300,
  className,
  ...props
}: SkeletonGroupProps) {
  const late = useLoadingDelay(loading, delay);

  const [kept, setKept] = useState(loading);
  if (loading && !kept) setKept(true);
  const swapping = kept && !loading;

  useEffect(() => {
    if (!swapping) return;
    const timer = window.setTimeout(() => setKept(false), ENTER_BACKSTOP);
    return () => window.clearTimeout(timer);
  }, [swapping]);

  return (
    <>
      <div
        aria-busy={loading || undefined}
        className={className ? `${styles.group} ${className}` : styles.group}
        {...props}
      >
        {kept && (
          <div className={styles.fallback} aria-hidden="true" data-shown={late || undefined}>
            {fallback}
          </div>
        )}
        {!loading && (
          <div
            className={styles.content}
            data-enter={swapping || undefined}
            onAnimationEnd={(event) => {
              if (event.target === event.currentTarget) setKept(false);
            }}
          >
            {children}
          </div>
        )}
      </div>
      {/* Outside aria-busy, which screen readers may hold back. */}
      <span role="status" className={styles.srOnly}>
        {late ? label : ""}
      </span>
    </>
  );
}

/* The pill's flight from one item to the next, shared by Tabs and the
   Segmented control so the two move as one family. The resting position is
   the caller's; this plays the move between two spans on top of it. */

/** A pill's offset and length along its track, and how far it's dipped. */
export type PillSpan = { start: number; length: number; dip?: number };

/** How deep the pill dips mid-flight, in px: none. A dip (and a spring on
 *  the leading edge) read as organic, a blob more than a control. */
const MAX_DIP = 0;

function token(el: Element, name: string, fallback: string) {
  return getComputedStyle(el).getPropertyValue(name).trim() || fallback;
}

function ms(value: string) {
  return value.endsWith("ms") ? parseFloat(value) : parseFloat(value) * 1000;
}

/** A `linear(...)` easing token as a function of progress, for sampling in JS. */
function curve(value: string): (t: number) => number {
  const points = value.startsWith("linear(") ? value.slice(7, -1).split(",").map(parseFloat) : [];
  if (points.length < 2 || points.some(Number.isNaN)) return (t) => 1 - (1 - t) ** 3;
  return (t) => {
    const at = Math.min(Math.max(t, 0), 1) * (points.length - 1);
    const i = Math.min(Math.floor(at), points.length - 2);
    return points[i] + (points[i + 1] - points[i]) * (at - i);
  };
}

/** Where the pill is along its track right now, mid-animation included. */
function translated(el: HTMLElement, vertical: boolean) {
  const transform = getComputedStyle(el).transform;
  if (!transform || transform === "none") return 0;
  const matrix = new DOMMatrixReadOnly(transform);
  return vertical ? matrix.m42 : matrix.m41;
}

/** Stops a flight in progress and returns where it left the pill on screen, or null if it was still. */
export function stopPill(indicator: HTMLElement, vertical = false): PillSpan | null {
  const running = indicator.getAnimations();
  if (!running.length) return null;
  const box = indicator.getBoundingClientRect();
  const span = {
    start: translated(indicator, vertical),
    length: vertical ? box.height : box.width,
    dip: Math.max(0, vertical ? indicator.offsetWidth - box.width : indicator.offsetHeight - box.height),
  };
  running.forEach((a) => a.cancel());
  return span;
}

/**
 * Flies the pill from one span to another: the edge facing the new item
 * leads, the far edge follows, both on the glide (no overshoot), so the
 * pill stretches a little toward the new item and settles once. Length
 * animates, not scale, which would squash the round ends. Under reduced
 * motion it doesn't play.
 */
export function flyPill(indicator: HTMLElement, from: PillSpan, to: PillSpan, vertical = false) {
  if (matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  const duration = ms(token(indicator, "--ui-dur-glide", "320ms"));
  const lead = curve(token(indicator, "--ui-ease-glide", ""));
  const follow = curve(token(indicator, "--ui-ease-glide", ""));
  const leadShare = ms(token(indicator, "--ui-dur-snap", "250ms")) / duration;
  const forward = to.start > from.start;
  const fromDip = from.dip ?? 0;
  // The dip only ever shrinks the pill, so nothing pokes out of the track.
  const full = vertical ? indicator.offsetWidth : indicator.offsetHeight;
  const travel = Math.abs(to.start + to.length / 2 - (from.start + from.length / 2));
  const dip = Math.min(MAX_DIP, travel / 30);
  const frames: Keyframe[] = [];
  for (let i = 0; i <= 24; i++) {
    const t = i / 24;
    const fast = lead(Math.min(t / leadShare, 1));
    const slow = follow(t);
    const near = from.start + (to.start - from.start) * (forward ? slow : fast);
    const far = from.start + from.length + (to.start + to.length - from.start - from.length) * (forward ? fast : slow);
    const p = Math.min(Math.max((fast + slow) / 2, 0), 1);
    const d = fromDip * (1 - p) + dip * Math.sin(Math.PI * p);
    frames.push(
      vertical
        ? { transform: `translate(${d / 2}px, ${near}px)`, height: `${far - near}px`, width: `${full - d}px` }
        : { transform: `translate(${near}px, ${d / 2}px)`, width: `${far - near}px`, height: `${full - d}px` },
    );
  }
  indicator.animate(frames, { duration, easing: "linear" });
}

@layer theme, base, components, utilities;

.pause {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  .tabs {
    display: grid;
    gap: var(--ui-space-4);
    min-width: 0;
    font-family: var(--ui-font-sans);
  }

  .list {
    position: relative;
    isolation: isolate;
    display: flex;
    justify-self: start;
    max-width: 100%;
    /* The track the Segmented control shares: --ui-track-* in the tokens. */
    padding: var(--ui-track-inset);
    border-radius: var(--ui-radius-full);
    box-shadow: var(--ui-track-edge);
    overflow-x: auto;
    /* Also blocks the browser's back-swipe gesture. */
    overscroll-behavior-inline: none;
    /* Keeps a selected tab scrolled clear of the edge fade. */
    scroll-padding-inline: var(--ui-space-6);
    scrollbar-width: none;
  }

  .list::-webkit-scrollbar {
    display: none;
  }

  .list[data-overflow-end] {
    mask-image: linear-gradient(to left, transparent, black var(--ui-space-6));
  }

  .list[data-overflow-start] {
    mask-image: linear-gradient(to right, transparent, black var(--ui-space-6));
  }

  :is([dir="rtl"]) .list[data-overflow-end] {
    mask-image: linear-gradient(to right, transparent, black var(--ui-space-6));
  }

  :is([dir="rtl"]) .list[data-overflow-start] {
    mask-image: linear-gradient(to left, transparent, black var(--ui-space-6));
  }

  .list[data-overflow-start][data-overflow-end] {
    mask-image: linear-gradient(
      to right,
      transparent,
      black var(--ui-space-6),
      black calc(100% - var(--ui-space-6)),
      transparent
    );
  }

  /* Base UI's Indicator places it on the selected tab through its CSS
     variables; the flight between tabs is a script animation on top. */
  .indicator {
    position: absolute;
    top: var(--ui-track-inset);
    left: 0;
    z-index: -1;
    width: var(--active-tab-width);
    height: var(--ui-control-sm);
    border-radius: var(--ui-radius-full);
    background: var(--ui-track-pill);
    transform: translateX(var(--active-tab-left));
    contain: strict;
    pointer-events: none;
  }

  .tab {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    flex-shrink: 0;
    height: var(--ui-control-sm);
    padding-inline: 14px;
    border: 0;
    border-radius: var(--ui-radius-full);
    background: transparent;
    color: var(--ui-muted);
    /* One weight for every state: bolding the selected tab would widen it. */
    font: var(--ui-weight-medium) var(--ui-text-md) / 1 var(--ui-font-sans);
    white-space: nowrap;
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      color var(--ui-dur-instant) var(--ui-ease-color),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .tab[data-active] {
    color: var(--ui-foreground);
  }

  /* Until the Indicator has measured, the selected tab carries the pill itself. */
  .list:not(:has(> .indicator:not([hidden]))) .tab[data-active] {
    background: var(--ui-track-pill);
  }

  @media (hover: hover) {
    .tab:hover:not([data-active]) {
      color: var(--ui-foreground);
    }
  }

  .tab:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .tab svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    pointer-events: none;
  }

  /* ---------- Count ---------- */

  .count {
    color: var(--ui-subtle);
    font-weight: var(--ui-weight-regular);
    font-variant-numeric: tabular-nums;
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .tab[data-active] .count {
    color: var(--ui-muted);
  }

  @media (hover: hover) {
    .tab:hover:not([data-active]) .count {
      color: var(--ui-muted);
    }
  }

  @media (pointer: coarse) {
    .tab::after {
      content: "";
      position: absolute;
      inset: -4px 0;
    }
  }

  /* ---------- Vertical ---------- */

  /* The 480px container breakpoint below must match the script, which reads
     the axis from the layout. */
  .tabs[data-layout="vertical"] {
    container-type: inline-size;
    grid-template-columns: auto minmax(0, 1fr);
    column-gap: var(--ui-space-6);
    align-items: start;
  }

  .tabs[data-layout="vertical"] > * {
    grid-column: 1 / -1;
  }

  @container (width >= 480px) {
    .tabs[data-layout="vertical"] > * {
      grid-column: auto;
    }

    .tabs[data-layout="vertical"] > .list {
      flex-direction: column;
      justify-self: stretch;
      min-width: 160px;
      padding: 0;
      border-radius: 0;
      box-shadow: none;
      overflow: visible;
      mask-image: none;
    }

    .tabs[data-layout="vertical"] > .list > .indicator {
      top: 0;
      width: 100%;
      height: var(--active-tab-height);
      transform: translateY(var(--active-tab-top));
    }

    .tabs[data-layout="vertical"] > .list > .tab {
      justify-content: flex-start;
    }

    .tabs[data-layout="vertical"] > .list > .tab > .count {
      margin-inline-start: auto;
      padding-inline-start: var(--ui-space-3);
    }

    /* Rows touch, so the hit area can't extend past them; the row grows instead. */
    @media (pointer: coarse) {
      .tabs[data-layout="vertical"] > .list > .tab {
        height: 40px;
      }
      .tabs[data-layout="vertical"] > .list > .tab::after {
        inset: 0;
      }
    }
  }

  .panel {
    min-width: 0;
    border-radius: var(--ui-radius-md);
  }

  .panel:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .panels {
    display: grid;
  }

  .panel[data-crossfade] {
    grid-area: 1 / 1;
    /* Base UI marks unselected panels hidden; here they still hold the cell. */
    display: block;
    opacity: 0;
    visibility: hidden;
    transition:
      opacity var(--ui-dur-instant) var(--ui-ease-color),
      visibility 0s linear var(--ui-dur-instant);
  }

  .panel[data-crossfade][data-selected] {
    opacity: 1;
    visibility: visible;
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2),
      visibility 0s;
  }

  @media (prefers-reduced-motion: reduce) {
    .panel[data-crossfade],
    .panel[data-crossfade][data-selected] {
      transition: none;
    }
  }
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { Tabs as BaseTabs } from "@base-ui/react/tabs";
import { DirectionProvider } from "@base-ui/react/direction-provider";
import { TextMorph } from "../text-morph/text-morph";
import { flyPill, stopPill } from "./pill-flight";
import styles from "./tabs.module.css";

type Orientation = "horizontal" | "vertical";

type TabsContextValue = {
  value: string;
  crossfade: boolean;
  manual: boolean;
  setAxis: (axis: Orientation) => void;
  register: (value: string) => () => void;
};

const TabsContext = createContext<TabsContextValue | null>(null);

function useTabs(part: string) {
  const context = useContext(TabsContext);
  if (!context) throw new Error(`<${part}> must be inside <Tabs>.`);
  return context;
}

type TabsProps = Omit<ComponentProps<"div">, "defaultValue" | "onChange"> & {
  /** Controlled value. Pair with `onValueChange`. */
  value?: string;
  /** Uncontrolled starting value, used when the URL has no valid `param`. */
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Arrow keys move focus only; Enter or Space selects. Use when showing a panel is slow. */
  manual?: boolean;
  /** Stack panels in one cell and crossfade between them. */
  crossfade?: boolean;
  /** Keep the selected tab in this search param (`?tab=notes`). Uncontrolled only. */
  param?: string;
  /** `vertical` puts the tabs in a column beside the panels; under 480px wide it falls back to a row. */
  orientation?: Orientation;
};

export function Tabs({
  value: controlledValue,
  defaultValue,
  onValueChange,
  manual = false,
  crossfade = false,
  param,
  orientation = "horizontal",
  className,
  children,
  ...props
}: TabsProps) {
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue ?? "");
  const value = controlledValue ?? uncontrolledValue;
  const controlled = controlledValue !== undefined;
  // The axis the list is laid out on now. A vertical list falls back to a row
  // under 480px, and Base UI's arrow keys follow what's on screen.
  const [axis, setAxis] = useState<Orientation>(orientation);

  // Tabs register their values so a URL can't select a tab that doesn't exist.
  const values = useRef(new Set<string>());
  const register = useCallback((v: string) => {
    values.current.add(v);
    return () => {
      values.current.delete(v);
    };
  }, []);

  const select = useCallback(
    (next: string) => {
      if (!controlled) setUncontrolledValue(next);
      onValueChange?.(next);
      if (param && !controlled) {
        const url = new URL(window.location.href);
        url.searchParams.set(param, next);
        window.history.replaceState(window.history.state, "", url);
      }
    },
    [controlled, onValueChange, param],
  );

  // A layout effect, so children's have run and every tab is registered.
  useLayoutEffect(() => {
    if (!param || controlled) return;
    function sync() {
      const fromUrl = new URLSearchParams(window.location.search).get(param!);
      setUncontrolledValue(fromUrl && values.current.has(fromUrl) ? fromUrl : (defaultValue ?? ""));
    }
    sync();
    window.addEventListener("popstate", sync);
    return () => window.removeEventListener("popstate", sync);
  }, [param, controlled, defaultValue]);

  return (
    <TabsContext value={{ value, crossfade, manual, setAxis, register }}>
      <BaseTabs.Root
        // Always controlled: the URL and `param` live here, not in Base UI.
        value={value === "" ? null : value}
        onValueChange={(next, details) => {
          // Only user picks; ignore Base UI's own fallbacks for missing tabs.
          if (details.reason !== "none" || typeof next !== "string") return;
          select(next);
        }}
        orientation={axis}
        className={className ? `${styles.tabs} ${className}` : styles.tabs}
        data-layout={orientation}
        {...props}
      >
        {children}
      </BaseTabs.Root>
    </TabsContext>
  );
}

type TabListProps = Omit<ComponentProps<"div">, "role"> & {
  /** Names the set of tabs for screen readers, e.g. "Estimate sections". */
  "aria-label"?: string;
  "aria-labelledby"?: string;
};

/** The axis the list is laid out on now: read, not assumed, since the CSS can fall back to a row. */
function axisOf(list: HTMLElement): Orientation {
  return getComputedStyle(list).flexDirection.startsWith("column") ? "vertical" : "horizontal";
}

/** A tab's offset and length along the list, measured the way Base UI places the indicator. */
function span(tab: HTMLElement, list: HTMLElement, vertical: boolean) {
  const t = tab.getBoundingClientRect();
  const l = list.getBoundingClientRect();
  return vertical
    ? { start: t.top - l.top + list.scrollTop - list.clientTop, length: t.height }
    : { start: t.left - l.left + list.scrollLeft - list.clientLeft, length: t.width };
}

export function TabList({ className, children, ...props }: TabListProps) {
  const { value, manual, setAxis } = useTabs("TabList");
  const listRef = useRef<HTMLDivElement>(null);
  const indicatorRef = useRef<HTMLSpanElement>(null);
  const [direction, setDirection] = useState<"ltr" | "rtl">("ltr");
  const previous = useRef<string | null>(null);
  // Nothing animates until the first paint, so a tab picked from the URL is simply there.
  const painted = useRef(false);
  useEffect(() => {
    let frame = requestAnimationFrame(() => {
      frame = requestAnimationFrame(() => {
        painted.current = true;
      });
    });
    return () => cancelAnimationFrame(frame);
  }, []);

  // Base UI's Indicator rests the pill on the selected tab through its CSS
  // variables. On a change of tab, this plays the flight between them on top.
  useLayoutEffect(() => {
    const list = listRef.current;
    const indicator = indicatorRef.current;
    const from = previous.current;
    previous.current = value;
    if (!list || !indicator || from === null || from === value) return;
    const tab = list.querySelector<HTMLElement>('[role="tab"][data-active]');
    const last = Array.from(list.querySelectorAll<HTMLElement>('[role="tab"]')).find((t) => t.dataset.value === from);
    if (!tab || !last) return;

    const vertical = axisOf(list) === "vertical";
    // A change mid-move starts from where the pill is on screen.
    const origin = stopPill(indicator, vertical) ?? span(last, list, vertical);
    if (!painted.current) return;
    flyPill(indicator, origin, span(tab, list, vertical), vertical);
  }, [value]);

  useLayoutEffect(() => {
    const list = listRef.current;
    if (!list) return;
    setAxis(axisOf(list));
    setDirection(getComputedStyle(list).direction === "rtl" ? "rtl" : "ltr");
  }, [setAxis]);

  useEffect(() => {
    const list = listRef.current;
    if (!list) return;
    let frame = 0;
    const edges = () => {
      const max = list.scrollWidth - list.clientWidth;
      const start = Math.abs(list.scrollLeft);
      list.toggleAttribute("data-overflow-start", start > 1);
      list.toggleAttribute("data-overflow-end", max - start > 1);
    };
    const observer = new ResizeObserver(() => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => setAxis(axisOf(list)));
      edges();
    });
    observer.observe(list);
    // The scrollbar is hidden, so a vertical wheel scrolls the tabs; at either
    // end it goes back to scrolling the page.
    const wheel = (event: WheelEvent) => {
      if (event.ctrlKey || event.shiftKey || Math.abs(event.deltaX) >= Math.abs(event.deltaY)) return;
      const max = list.scrollWidth - list.clientWidth;
      if (max <= 1) return;
      const unit = event.deltaMode === 1 ? 16 : event.deltaMode === 2 ? list.clientWidth : 1;
      const rtl = getComputedStyle(list).direction === "rtl";
      const by = event.deltaY * unit * (rtl ? -1 : 1);
      const start = Math.abs(list.scrollLeft);
      if ((by > 0) !== rtl ? max - start <= 1 : start <= 1) return;
      event.preventDefault();
      list.scrollBy({ left: by });
    };
    list.addEventListener("scroll", edges, { passive: true });
    list.addEventListener("wheel", wheel, { passive: false });
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      list.removeEventListener("scroll", edges);
      list.removeEventListener("wheel", wheel);
    };
  }, [setAxis]);

  return (
    <DirectionProvider direction={direction}>
      <BaseTabs.List
        ref={listRef}
        activateOnFocus={!manual}
        className={className ? `${styles.list} ${className}` : styles.list}
        {...props}
      >
        <BaseTabs.Indicator ref={indicatorRef} className={styles.indicator} aria-hidden="true" />
        {children}
      </BaseTabs.List>
    </DirectionProvider>
  );
}

type TabProps = Omit<ComponentProps<"button">, "value" | "role"> & {
  value: string;
  children: ReactNode;
  /** A count after the label, read as part of the tab's name ("Guests, 14"). */
  count?: number | string;
};

export function Tab({ value, count, className, children, onFocus, ...props }: TabProps) {
  const { register } = useTabs("Tab");

  useLayoutEffect(() => register(value), [register, value]);

  return (
    <BaseTabs.Tab
      value={value}
      data-value={value}
      className={className ? `${styles.tab} ${className}` : styles.tab}
      onFocus={(event) => {
        onFocus?.(event);
        // Arrowing to a tab hidden past the fade scrolls it into view.
        if (event.currentTarget.matches(":focus-visible")) {
          event.currentTarget.scrollIntoView({ block: "nearest", inline: "nearest" });
        }
      }}
      {...props}
    >
      {count === undefined || count === "" ? (
        children
      ) : (
        <>
          <span className={styles.label}>
            {children}
            {/* Screen-reader-only pause, so the name reads "Guests, 14". */}
            <span className={styles.pause}>,</span>
          </span>
          <span className={styles.count}>
            <TextMorph>{String(count)}</TextMorph>
          </span>
        </>
      )}
    </BaseTabs.Tab>
  );
}

type TabPanelProps = Omit<ComponentProps<"div">, "role"> & {
  value: string;
};

export function TabPanel({ value, className, children, ...props }: TabPanelProps) {
  const { value: selected, crossfade } = useTabs("TabPanel");
  return (
    <BaseTabs.Panel
      value={value}
      // Unselected panels stay mounted, so their state survives a switch.
      keepMounted
      data-crossfade={crossfade || undefined}
      data-selected={value === selected || undefined}
      className={className ? `${styles.panel} ${className}` : styles.panel}
      {...props}
    >
      {children}
    </BaseTabs.Panel>
  );
}

/** Wraps the panels when `crossfade` is on, so they share one grid cell. */
export function TabPanels({ className, ...props }: ComponentProps<"div">) {
  return <div className={className ? `${styles.panels} ${className}` : styles.panels} {...props} />;
}

@layer theme, base, components, utilities;

@layer components {
  /* Base UI's Positioner places this element; the surface inside it animates. */
  .positioner {
    z-index: 60;
    max-width: min(280px, calc(100vw - 16px));
  }

  .surface {
    position: relative;
    display: flex;
    align-items: baseline;
    gap: var(--ui-space-2);
    width: max-content;
    max-width: 100%;
    box-sizing: border-box;
    padding: var(--ui-space-1) var(--ui-space-2);
    border-radius: var(--ui-radius-sm);
    background: var(--ui-ink);
    box-shadow: var(--ui-shadow-raised);
    color: var(--ui-on-ink);
    font: var(--ui-weight-medium) var(--ui-text-sm) / var(--ui-leading-sm) var(--ui-font-sans);
    text-wrap: pretty;
    transform-origin: var(--transform-origin);
    opacity: 1;
    scale: 1;
    filter: none;
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter),
      scale var(--ui-dur-fast) var(--ui-ease-enter),
      filter var(--ui-dur-fast) var(--ui-ease-enter);
  }

  .surface[hidden] {
    display: none;
  }

  .surface[data-starting-style],
  .surface[data-ending-style] {
    opacity: 0;
    scale: 0.97;
    filter: blur(2px);
  }

  .surface[data-ending-style] {
    transition-duration: var(--ui-dur-instant);
    transition-timing-function: var(--ui-ease-exit);
  }

  /* Warm: opened while another tooltip was showing or had just closed. */
  .surface[data-warm] {
    transition-duration: 0s;
  }

  .content {
    min-width: 0;
  }

  .kbd {
    flex-shrink: 0;
    color: var(--ui-on-ink-muted);
    font-family: var(--ui-font-mono);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-medium);
    /* Otherwise the mono face on the baseline makes the tooltip taller. */
    line-height: 1;
  }

  /* Base UI sets the arrow's offset along the edge; the SVG points down by default. */
  .arrow {
    position: absolute;
    width: 12px;
    height: 6px;
  }

  .arrow svg {
    display: block;
    width: 12px;
    height: 6px;
    fill: var(--ui-ink);
  }

  .arrow[data-side="top"] {
    top: 100%;
  }

  .arrow[data-side="bottom"] {
    bottom: 100%;
    rotate: 180deg;
  }

  .arrow[data-side="left"] {
    left: calc(100% - 3px);
    rotate: -90deg;
  }

  .arrow[data-side="right"] {
    right: calc(100% - 3px);
    rotate: 90deg;
  }

  @media (prefers-reduced-motion: reduce) {
    .surface {
      transition: none;
    }
    .surface[data-starting-style],
    .surface[data-ending-style] {
      scale: none;
    }
  }
}

"use client";

import {
  cloneElement,
  useEffect,
  useId,
  useRef,
  useState,
  type ReactElement,
  type ReactNode,
} from "react";
import { flushSync } from "react-dom";
import { Tooltip as BaseTooltip } from "@base-ui/react/tooltip";
import styles from "./tooltip.module.css";

type Side = "top" | "bottom" | "left" | "right";
type Align = "start" | "center" | "end";

/** Hover delay before the first tooltip opens. */
const OPEN_DELAY = 500;
/** After a tooltip closes, others open instantly for this long. */
const WARM_WINDOW = 300;

type Handle = { finishExit: () => void; rect: () => DOMRect | undefined };

// Shared by every tooltip on the page, so the component needs no provider.
let active: Handle | null = null;
let exiting: Handle | null = null;
let lastClosedAt = -Infinity;
// Where the previous tooltip sat, so a warm hand-off can slide from there.
let handoff: DOMRect | undefined;

function isWarm() {
  return active !== null || performance.now() - lastClosedAt < WARM_WINDOW;
}

/** A CSS time token in ms. Browsers may report "250ms" as ".25s". */
function ms(value: string, fallback: number) {
  const n = parseFloat(value);
  if (Number.isNaN(n)) return fallback;
  return value.trim().endsWith("ms") ? n : n * 1000;
}

type TriggerProps = { "aria-describedby"?: string };

type TooltipProps = {
  /** What the tooltip says; never the only place something lives. */
  content: ReactNode;
  /** A shortcut shown after the text, like "⌘C". */
  kbd?: string;
  side?: Side;
  align?: Align;
  /** Show an arrow pointing at the trigger. */
  arrow?: boolean;
  /** Link it with `aria-describedby`. Turn off when it only repeats the trigger's `aria-label`. */
  describe?: boolean;
  /** Hover delay before the first tooltip opens, in ms. */
  delay?: number;
  /** One focusable element. Disabled controls need a wrapper; see the guide. */
  children: ReactElement<TriggerProps>;
};

export function Tooltip({
  content,
  kbd,
  side = "top",
  align = "center",
  arrow = false,
  describe = true,
  delay = OPEN_DELAY,
  children,
}: TooltipProps) {
  const tipId = `${useId()}-tooltip`;
  const popupRef = useRef<HTMLDivElement>(null);
  const [triggerEl, setTriggerEl] = useState<HTMLElement | null>(null);
  const [open, setOpen] = useState(false);
  // Read when the pointer arrives, so Base UI sees a 0ms delay while another tooltip is warm.
  const [warm, setWarm] = useState(false);
  const [instant, setInstant] = useState(false);

  const handle = useRef<Handle>({
    finishExit: () => {
      setInstant(true);
      popupRef.current?.getAnimations().forEach((a) => a.finish());
    },
    // Open or still fading out.
    rect: () => {
      const popup = popupRef.current;
      return popup && +getComputedStyle(popup).opacity > 0 ? popup.getBoundingClientRect() : undefined;
    },
  });

  function onOpenChange(next: boolean) {
    const self = handle.current;
    if (next) {
      const skipEntrance = isWarm();
      const previous = active ?? exiting;
      if (previous && previous !== self) {
        handoff = previous.rect();
        // Don't cross-fade: the outgoing one just goes.
        previous.finishExit();
      }
      active = self;
      exiting = null;
      setInstant(skipEntrance);
    } else {
      if (active === self) {
        active = null;
        lastClosedAt = performance.now();
      }
      exiting = self;
    }
    setOpen(next);
  }

  // A warm hand-off slides from where the previous tooltip sat.
  useEffect(() => {
    if (!open || !instant) return;
    const from = handoff;
    handoff = undefined;
    if (!from || matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const frame = requestAnimationFrame(() => {
      const popup = popupRef.current;
      if (!popup) return;
      const to = popup.getBoundingClientRect();
      const dx = from.left + from.width / 2 - (to.left + to.width / 2);
      const dy = from.top - to.top;
      if (Math.abs(dx) < 1 && Math.abs(dy) < 1) return;
      const style = getComputedStyle(popup);
      popup.animate(
        { translate: [`${dx}px ${dy}px`, "0 0"] },
        {
          duration: ms(style.getPropertyValue("--ui-dur-snap"), 250),
          easing: style.getPropertyValue("--ui-ease-snap").trim() || "ease-out",
        },
      );
    });
    return () => cancelAnimationFrame(frame);
  }, [open, instant]);

  useEffect(() => {
    const self = handle.current;
    return () => {
      if (active === self) active = null;
      if (exiting === self) exiting = null;
    };
  }, []);

  const describedBy = [children.props["aria-describedby"], describe ? tipId : null].filter(Boolean).join(" ");

  return (
    <BaseTooltip.Root
      open={open}
      onOpenChange={onOpenChange}
      onOpenChangeComplete={(next) => {
        if (next) return;
        if (exiting === handle.current) exiting = null;
        setInstant(false);
      }}
    >
      <BaseTooltip.Trigger
        ref={setTriggerEl}
        delay={warm ? 0 : delay}
        // Pointer events have continuous priority; flush so the delay is in place before mouseenter.
        onPointerEnter={() => flushSync(() => setWarm(isWarm()))}
        render={cloneElement(children, { "aria-describedby": describedBy || undefined })}
      />
      {/* Kept mounted so `aria-describedby` points at real text even while closed. */}
      <BaseTooltip.Portal
        keepMounted={describe}
        container={triggerEl?.closest<HTMLElement>("dialog[open], [data-theme]") ?? undefined}
      >
        <BaseTooltip.Positioner
          className={styles.positioner}
          side={side}
          align={align}
          sideOffset={arrow ? 10 : 6}
          collisionPadding={8}
        >
          <BaseTooltip.Popup
            ref={popupRef}
            id={tipId}
            role="tooltip"
            className={styles.surface}
            data-warm={instant || undefined}
          >
            <span className={styles.content}>{content}</span>
            {kbd && <kbd className={styles.kbd}>{kbd}</kbd>}
            {arrow && (
              <BaseTooltip.Arrow className={styles.arrow}>
                <svg viewBox="0 0 12 6" aria-hidden="true">
                  <path d="M0 0h12L7.2 5.1a1.6 1.6 0 0 1-2.4 0z" />
                </svg>
              </BaseTooltip.Arrow>
            )}
          </BaseTooltip.Popup>
        </BaseTooltip.Positioner>
      </BaseTooltip.Portal>
    </BaseTooltip.Root>
  );
}

@layer theme, base, components, utilities;

.label {
  composes: truncate from "../text/text.module.css";
}

.headingLabel {
  composes: truncate from "../text/text.module.css";
}

/* One line, faded at the end when cut; the whole title is in `title`. */
.recentTitle {
  composes: truncate from "../text/text.module.css";
}

.renameBusy {
  composes: sweep from "../text/text.module.css";
}

.showAll {
  composes: row;
}

.menuName,
.menuDetail {
  composes: truncate from "../text/text.module.css";
}

@layer components {
  /* The geometry every part reads, on the sidebar and on its phone drawer.
     Rows are 32px, Tabs' height; collapsed, each is a 44px icon capsule (the
     capsule ratio of a 32px button), so the rail is that plus the padding on
     both sides. Content starts --sidebar-inset into a row: where a 16px icon
     sits centered in the capsule, so icons don't move as the sidebar folds. */
  .vars {
    --sidebar-width: 264px;
    --sidebar-pad: var(--ui-space-2);
    --sidebar-row: var(--ui-control-sm);
    --sidebar-capsule: calc(var(--sidebar-row) * var(--ui-capsule));
    --sidebar-rail: calc(var(--sidebar-capsule) + var(--sidebar-pad) * 2);
    --sidebar-inset: calc((var(--sidebar-capsule) - 16px) / 2);
    --sidebar-more: calc(24px * var(--ui-capsule));
    --sidebar-bg: var(--ui-canvas);
    /* Opaque versions of the row fills, so the collapsed count can cut out of them. */
    --sidebar-bg-current: color-mix(in oklch, var(--ui-foreground) 8%, var(--sidebar-bg));
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
  }

  /* A finger gets 40px rows; collapsed, that's Nav rail's 55px capsule. */
  @media (pointer: coarse) {
    .vars {
      --sidebar-row: var(--ui-control-md);
    }
  }

  /* ---------- Frame ---------- */

  /* On the canvas, one step under the page beside it: the change of surface is
     the edge, as in Chat app. Its width glides between the full sidebar and the
     rail; the parent lays it out in a row (flex or grid, `auto` column). */
  .sidebar {
    position: relative;
    display: flex;
    flex-direction: column;
    flex-shrink: 0;
    box-sizing: border-box;
    width: var(--sidebar-width);
    height: 100%;
    min-height: 0;
    overflow: clip;
    background: var(--sidebar-bg);
    color: var(--ui-foreground);
    font-family: var(--ui-font-sans);
    transition: width var(--ui-dur-panel) var(--ui-ease-expand);
  }

  .sidebar[data-collapsed] {
    width: var(--sidebar-rail);
    transition-duration: var(--ui-dur-base);
    transition-timing-function: var(--ui-ease-collapse);
  }

  /* On a phone it's a drawer instead; hidden here from the first paint. */
  @media (max-width: 767px) {
    .sidebar {
      display: none;
    }
  }

  .header {
    padding: var(--ui-space-2) var(--sidebar-pad) 0;
  }

  .footer {
    padding: var(--ui-space-2) var(--sidebar-pad);
  }

  /* Labels leave fast as the sidebar folds, and arrive half a beat after it
     starts to open, so text is never read mid-move. Icons hold still. */
  .label,
  .trailing,
  .chevron,
  .menuText,
  .scrollWrap {
    transition: opacity var(--ui-dur-fast) var(--ui-ease-enter) var(--ui-dur-instant);
  }

  .sidebar[data-collapsed] :is(.label, .trailing, .chevron, .menuText) {
    opacity: 0;
    transition: opacity var(--ui-dur-instant) var(--ui-ease-exit);
  }

  .sidebar[data-collapsed] .scrollWrap {
    opacity: 0;
    visibility: hidden;
    transition:
      opacity var(--ui-dur-instant) var(--ui-ease-exit),
      visibility 0s linear var(--ui-dur-instant);
  }

  /* ---------- Nav ---------- */

  .nav {
    position: relative;
    isolation: isolate;
    display: flex;
    flex: 1;
    flex-direction: column;
    min-height: 0;
  }

  .primary,
  .list {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: 2px;
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .primary {
    padding: var(--ui-space-2) var(--sidebar-pad) 0;
  }

  .cell {
    display: grid;
    min-width: 0;
  }

  .scrollWrap {
    display: flex;
    flex: 1;
    flex-direction: column;
    min-height: 0;
    margin-block-start: var(--ui-space-3);
  }

  .scroll {
    flex: 1;
    min-height: 0;
  }

  /* Held at the open width, so nothing rewraps while the sidebar folds over it. */
  .more {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: var(--ui-space-4);
    box-sizing: border-box;
    min-width: calc(var(--sidebar-width) - var(--scroll-area-bar, 0px));
    padding: 0 var(--sidebar-pad) var(--ui-space-4);
  }

  /* ---------- The pill ---------- */

  /* Only on screen while it flies between rows; at rest the current row
     paints the same flat pill itself. */
  .pill {
    position: absolute;
    top: 0;
    left: 0;
    z-index: -1;
    border-radius: var(--ui-radius-full);
    background: var(--ui-track-pill);
    contain: layout style size;
    pointer-events: none;
    visibility: hidden;
  }

  .nav[data-flying] > .pill {
    visibility: visible;
  }

  /* ---------- Rows ---------- */

  .row {
    position: relative;
    display: flex;
    align-items: center;
    gap: var(--ui-space-2);
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    height: var(--sidebar-row);
    margin: 0;
    padding: 0 var(--sidebar-inset);
    border: 0;
    border-radius: var(--ui-radius-full);
    background: transparent;
    /* Rows rest in the muted text color; hover brings the row up to the text
       color, as Nav rail's items do: no fill. Only the current row has one. */
    color: var(--ui-muted);
    font: var(--ui-weight-medium) var(--ui-text-md) / 1 var(--ui-font-sans);
    text-align: start;
    text-decoration: none;
    white-space: nowrap;
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      color var(--ui-dur-instant) var(--ui-ease-color);
  }

  @media (hover: hover) {
    .row:hover,
    .recentItem:hover .row {
      color: var(--ui-foreground);
    }
  }

  /* The current item: Tabs' flat pill, the same fill, no edge, no shadow. */
  .row[data-current] {
    background: var(--ui-track-pill);
    color: var(--ui-foreground);
  }

  .nav[data-flying] .row[data-current] {
    background: transparent;
  }

  /* The pill hands off without a fade: the row it leaves clears at once
     (no second, fading pill behind the flying one) and the row it lands on
     paints at once (no blink as the flying pill hides). Hover keeps its
     fade on every other row. */
  .row[data-current],
  .nav[data-flying] .row {
    transition: none;
  }

  .row:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .row[data-nested] {
    padding-inline-start: calc(var(--sidebar-inset) + 16px + var(--ui-space-2));
    font-weight: var(--ui-weight-regular);
  }

  .icon {
    display: grid;
    flex-shrink: 0;
    place-items: center;
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    color: var(--ui-muted);
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .icon > svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
  }

  .row[data-current] .icon {
    color: var(--ui-foreground);
  }

  @media (hover: hover) {
    .row:hover .icon {
      color: var(--ui-foreground);
    }
  }

  .label {
    flex: 1;
  }

  .trailing {
    display: flex;
    flex-shrink: 0;
    align-items: center;
    gap: 6px;
    margin-inline-start: auto;
  }

  /* A row's detail ("Away"): quiet, in the recent list's meta type. */
  .detail {
    color: var(--ui-subtle);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-regular);
    line-height: var(--ui-leading-sm);
    white-space: nowrap;
  }

  /* The shortcut is a hint: it shows on hover and focus, and stays in the
     collapsed rail's tooltip. */
  .kbd {
    color: var(--ui-subtle);
    font-weight: var(--ui-weight-regular);
    opacity: 0;
    transition: opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  .row:focus-visible .kbd {
    opacity: 1;
  }

  @media (hover: hover) {
    .row:hover .kbd {
      opacity: 1;
    }
  }

  .count,
  .corner {
    display: grid;
    place-items: center;
    box-sizing: border-box;
    min-width: 18px;
    height: 18px;
    padding-inline: 5px;
    border-radius: var(--ui-radius-full);
    background: var(--ui-accent);
    color: var(--ui-on-accent);
    font: var(--ui-weight-medium) var(--ui-text-sm) / 1 var(--ui-font-sans);
    font-variant-numeric: tabular-nums;
  }

  /* Collapsed, the count sits at the icon's top right, as on Nav rail, cut
     out of the glyph by a ring of whatever is behind it. */
  .corner {
    position: absolute;
    top: calc(var(--sidebar-row) / 2 - 16px);
    inset-inline-start: calc(var(--sidebar-inset) + 10px);
    box-shadow: 0 0 0 var(--ui-knockout) var(--sidebar-bg);
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ui-dur-instant) var(--ui-ease-exit);
  }

  .row[data-current] .corner {
    box-shadow: 0 0 0 var(--ui-knockout) var(--sidebar-bg-current);
  }

  .sidebar[data-collapsed] .corner {
    opacity: 1;
    transition: opacity var(--ui-dur-fast) var(--ui-ease-enter) var(--ui-dur-instant);
  }

  /* Disclosure chevrons rest muted and come up to the text color with their row. */
  .chevron {
    flex-shrink: 0;
    margin-inline-start: auto;
    color: var(--ui-muted);
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter) var(--ui-dur-instant),
      color var(--ui-dur-instant) var(--ui-ease-color);
  }

  /* A group heading is 13px text: its chevron is the sm icon. */
  .headingButton .chevron {
    width: var(--ui-icon-chevron);
    height: var(--ui-icon-chevron);
  }

  @media (hover: hover) {
    :is(.row, .headingButton, .menuButton):hover .chevron {
      color: var(--ui-foreground);
    }
  }

  /* ---------- Folding ---------- */

  .fold {
    display: grid;
    grid-template-rows: 0fr;
    transition: grid-template-rows var(--ui-dur-base) var(--ui-ease-collapse);
  }

  .fold[data-open] {
    grid-template-rows: 1fr;
    transition: grid-template-rows var(--ui-dur-panel) var(--ui-ease-expand);
  }

  .foldInner {
    display: grid;
    min-height: 0;
    overflow: hidden;
    opacity: 0;
    transition: opacity var(--ui-dur-instant) var(--ui-ease-exit);
  }

  .fold[data-open] > .foldInner {
    opacity: 1;
    transition: opacity var(--ui-dur-fast) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2);
  }

  /* The rows inside start 2px below the group's row, as between any two rows. */
  .fold > .foldInner > .list {
    padding-block-start: 2px;
  }

  /* ---------- Sections ---------- */

  .section {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    min-width: 0;
  }

  .heading {
    margin: 0;
    font: inherit;
  }

  .headingText,
  .headingButton {
    display: flex;
    align-items: center;
    gap: var(--ui-space-2);
    box-sizing: border-box;
    width: 100%;
    height: var(--sidebar-row);
    padding: 0 var(--sidebar-inset);
    color: var(--ui-muted);
    font: var(--ui-weight-medium) var(--ui-text-sm) / 1 var(--ui-font-sans);
  }

  .headingButton {
    border: 0;
    border-radius: var(--ui-radius-full);
    background: transparent;
    text-align: start;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      color var(--ui-dur-instant) var(--ui-ease-color);
  }

  @media (hover: hover) {
    .headingButton:hover {
      color: var(--ui-foreground);
    }
  }

  .headingButton:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  /* ---------- Recent ---------- */

  .recentItem {
    display: grid;
    grid-template-rows: 1fr;
    min-width: 0;
  }

  .recentInner {
    position: relative;
    min-width: 0;
    min-height: 0;
  }

  /* A removed chat fades on the press, then its space folds. */
  .recentItem[data-state="leave"] {
    grid-template-rows: 0fr;
    opacity: 0;
    transition:
      opacity var(--ui-dur-instant) var(--ui-ease-exit),
      grid-template-rows var(--ui-dur-base) var(--ui-ease-collapse) var(--ui-dur-instant);
  }

  .recentItem[data-state="leave"] > .recentInner {
    overflow: hidden;
  }

  /* A chat that arrives (a new one, one just pinned) opens its space and fades in. */
  .recentItem[data-state="enter"] {
    animation: recent-open var(--ui-dur-panel) var(--ui-ease-expand);
  }

  .recentItem[data-state="enter"] > .recentInner {
    overflow: hidden;
    animation: recent-in var(--ui-dur-fast) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2) backwards;
  }

  @keyframes recent-open {
    from {
      grid-template-rows: 0fr;
    }
  }

  @keyframes recent-in {
    from {
      opacity: 0;
    }
  }

  .row[data-kind="recent"] {
    font-weight: var(--ui-weight-regular);
    font-size: var(--ui-text-sm);
  }

  .recentTitle {
    flex: 1;
    line-height: var(--ui-leading-sm);
  }

  /* Names and titles are people's own words and take their own direction
     (dir="auto"); they line up with the sidebar's start either way. Set from
     the measured direction: `:dir()` doesn't survive every CSS build. */
  .recentTitle,
  .menuName,
  .menuDetail,
  .renameInput {
    text-align: left;
  }

  [data-rtl] :is(.recentTitle, .menuName, .menuDetail, .renameInput) {
    text-align: right;
  }

  /* Room for the "…" while it shows, so the title fades out before it. */
  .recentItem[data-actions]:is(:hover, :focus-within, [data-menu-open]) .row,
  .recentItem[data-actions] .row[data-current] {
    padding-inline-end: calc(var(--sidebar-more) + 8px);
  }

  @media (hover: none), (pointer: coarse) {
    .recentItem[data-actions] .row {
      padding-inline-end: calc(var(--sidebar-more) + 8px);
    }
    /* The "…" is always there on touch, so it keeps the end. */
    .recentItem[data-actions] .recentMeta {
      display: none;
    }
    .recentItem[data-actions][data-meta]:is(:hover, :focus-within, [data-menu-open]) .row,
    .recentItem[data-actions][data-meta] .row[data-current] {
      padding-inline-end: calc(var(--sidebar-more) + 8px);
    }
  }

  /* Meta at the row's end (a time, faces): subtle, figures of equal width,
     at least as wide as the "…", which takes its place on hover, focus, the
     current row and while the menu is open. The row keeps its padding, so
     the title never moves when the two swap. */
  .recentMeta {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: flex-end;
    gap: var(--ui-gap-tight);
    min-width: var(--sidebar-more);
    color: var(--ui-subtle);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    font-variant-numeric: tabular-nums;
    transition: opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  .recentItem[data-meta]:is(:hover, :focus-within, [data-menu-open]) .row,
  .recentItem[data-meta] .row[data-current] {
    padding-inline-end: var(--sidebar-inset);
  }

  .recentItem[data-actions]:is(:hover, :focus-within, [data-menu-open]) .recentMeta,
  .recentItem[data-actions] .row[data-current] .recentMeta {
    opacity: 0;
  }

  /* The "…" capsule, 4px in from the row's round end, so the two are concentric.
     It shows on hover, focus, the current row and while its menu is open;
     always on touch. */
  .moreButton {
    position: absolute;
    inset-block: 0;
    inset-inline-end: 4px;
    display: grid;
    place-items: center;
    width: var(--sidebar-more);
    height: 24px;
    margin-block: auto;
    padding: 0;
    border: 0;
    border-radius: var(--ui-radius-full);
    background: transparent;
    color: var(--ui-muted);
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    transition:
      opacity var(--ui-dur-instant) var(--ui-ease-color),
      color var(--ui-dur-instant) var(--ui-ease-color),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  /* 40px to a finger without changing the row. */
  .moreButton::after {
    content: "";
    position: absolute;
    inset: -8px -4px;
  }

  @media (hover: hover) and (pointer: fine) {
    .moreButton {
      opacity: 0;
    }
    .recentItem:is(:hover, :focus-within, [data-menu-open]) .moreButton,
    .row[data-current] + .moreButton {
      opacity: 1;
    }
    .moreButton:hover {
      background: var(--ui-fill-strong);
      color: var(--ui-foreground);
    }
  }

  .recentItem[data-menu-open] .moreButton {
    background: var(--ui-fill-strong);
    color: var(--ui-foreground);
  }

  .moreButton:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .glyph {
    flex-shrink: 0;
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    fill: none;
    stroke: currentColor;
    stroke-width: var(--ui-icon-stroke, 1.5);
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  /* The title, editable where it sat: the text keeps its place in a field
     the row's shape. */
  .rename {
    display: grid;
    gap: var(--ui-space-1);
  }

  .renameInput {
    box-sizing: border-box;
    width: 100%;
    height: var(--sidebar-row);
    margin: 0;
    padding: 0 var(--sidebar-inset);
    border: 0;
    border-radius: var(--ui-radius-full);
    background: var(--ui-surface);
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-field-focus);
    color: var(--ui-foreground);
    font: var(--ui-weight-regular) var(--ui-text-sm) / var(--ui-leading-sm) var(--ui-font-sans);
    outline: none;
  }

  .renameInput[aria-invalid] {
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-danger);
  }

  .renameBusy {
    --sweep-dim: 0.5;
  }

  @media (pointer: coarse) {
    .renameInput {
      font-size: var(--ui-text-touch);
    }
  }

  .renameError {
    margin: 0;
    padding: 0 var(--sidebar-inset) var(--ui-space-1);
    color: var(--ui-danger-text);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    text-wrap: pretty;
  }

  .showAll {
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
  }

  @media (hover: hover) {
    .showAll:hover {
      color: var(--ui-foreground);
    }
  }

  /* Empty: quiet words in the list's place, no drawing. */
  .empty {
    display: grid;
    gap: 2px;
    padding: var(--ui-space-1) var(--sidebar-inset) var(--ui-space-2);
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    text-wrap: pretty;
  }

  .empty > p {
    margin: 0;
  }

  .emptyTitle,
  .empty > p:first-child {
    color: var(--ui-foreground);
    font-weight: var(--ui-weight-medium);
  }

  /* One bone per title, in a row of the real height. */
  .skeleton {
    display: grid;
    gap: 2px;
  }

  .skeletonRow {
    display: flex;
    align-items: center;
    height: var(--sidebar-row);
    padding-inline: var(--sidebar-inset);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
  }

  /* ---------- Header and footer buttons ---------- */

  .menuButton {
    display: flex;
    align-items: center;
    gap: var(--ui-space-2);
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    height: var(--ui-control-md);
    margin: 0;
    /* The 24px mark centers on the icon column below it. */
    padding: 0 calc(var(--sidebar-inset) - 4px);
    border: 0;
    border-radius: var(--ui-radius-full);
    background: transparent;
    color: var(--ui-foreground);
    font: var(--ui-weight-medium) var(--ui-text-md) / 1 var(--ui-font-sans);
    letter-spacing: normal;
    text-align: start;
    white-space: nowrap;
    cursor: pointer;
    user-select: none;
    -webkit-tap-highlight-color: transparent;
    transition: background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  @media (hover: hover) {
    .menuButton:hover {
      background: var(--ui-fill);
    }
  }

  .menuButton[data-popup-open] {
    background: var(--ui-fill-strong);
  }

  .menuButton:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .media {
    display: grid;
    flex-shrink: 0;
    place-items: center;
    width: 24px;
    height: 24px;
  }

  /* The mark on a round ink tile: round, so it's concentric with the button. */
  .mark {
    display: grid;
    place-items: center;
    width: 24px;
    height: 24px;
    border-radius: var(--ui-radius-full);
    background: var(--ui-ink);
    color: var(--ui-on-ink);
  }

  .mark > svg {
    width: var(--ui-icon-xs);
    height: var(--ui-icon-xs);
  }

  .menuText {
    display: grid;
    flex: 1;
    min-width: 0;
  }

  .menuButton[data-kind="account"] .menuName,
  .menuDetail {
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
  }

  .menuDetail {
    color: var(--ui-muted);
    font-weight: var(--ui-weight-regular);
  }

  /* As wide as the button it opens from, when that's wider than a menu. */
  .menu[role="menu"] {
    min-width: max(var(--anchor-width, 0px), 220px);
  }

  /* ---------- Drawer ---------- */

  /* On a phone the drawer is the surface; the rows sit on it at its padding. */
  .drawer {
    --sidebar-bg: var(--ui-surface);
    --drawer-pad: var(--ui-space-4);
  }

  .drawer .primary {
    padding: 0;
  }

  .drawer .more {
    min-width: 0;
    margin-block-start: var(--ui-space-3);
    padding: 0;
  }

  /* The switcher is the drawer's title: centered on the title's line, its mark
     on the icon column below. */
  .drawer .menuButton {
    margin-block: calc((var(--ui-leading-2xl) - var(--ui-control-md)) / 2);
  }

  .drawerFooter {
    flex: 1;
    min-width: 0;
  }

  /* ---------- Toggle tooltip ---------- */

  .tip {
    display: inline-flex;
    align-items: baseline;
    gap: var(--ui-space-2);
  }

  .tipKbd {
    color: var(--ui-on-ink-muted);
  }

  @media (prefers-reduced-motion: reduce) {
    .sidebar,
    .sidebar[data-collapsed],
    .fold,
    .fold[data-open],
    .recentItem[data-state="leave"] {
      transition: none;
    }
    .label,
    .trailing,
    .chevron,
    .menuText,
    .scrollWrap,
    .corner,
    .sidebar[data-collapsed] :is(.label, .trailing, .chevron, .menuText, .scrollWrap, .corner) {
      transition: none;
    }
    .recentItem[data-state="enter"],
    .recentItem[data-state="enter"] > .recentInner {
      animation: none;
    }
  }

  @media (forced-colors: active) {
    .row[data-current] {
      outline: 1px solid CanvasText;
      outline-offset: -1px;
    }
  }
}

"use client";

import {
  createContext,
  use,
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
  type KeyboardEvent,
  type ReactNode,
  type RefObject,
} from "react";
import { DirectionProvider } from "@base-ui/react/direction-provider";
import { Button } from "../button/button";
import { Drawer } from "../drawer/drawer";
import { DropdownMenu, MenuItem, MenuSeparator } from "../dropdown-menu/dropdown-menu";
import { Icon } from "../icons/icons";
import { Kbd } from "../kbd/kbd";
import { NavRailTooltipGroup, NavRailTrigger } from "../nav-rail/nav-rail";
import { ScrollArea } from "../scroll-area/scroll-area";
import { SkeletonGroup, SkeletonText } from "../skeleton/skeleton";
import { flyPill, stopPill } from "../tabs/pill-flight";
import { Tooltip } from "../tooltip/tooltip";
import styles from "./sidebar.module.css";

/* Behavior comes from Base UI through the kit: the menus are Dropdown menu,
   the phone drawer is Drawer, the collapsed rail's one tooltip is Nav rail's.
   This file keeps the layout, the collapse, the pill and the recent list. */

/** Below this width the sidebar leaves the layout and opens as a drawer. Keep in sync with the CSS. */
export const SIDEBAR_DRAWER_QUERY = "(max-width: 767px)";

export type SidebarItem = {
  id: string;
  /** The item's name: its text, its accessible name and the collapsed rail's tooltip. */
  label: string;
  /** A 16px icon drawn in `currentColor`. Primary items need one: it's all the collapsed rail shows. */
  icon?: ReactNode;
  /** Renders a link instead of a button. */
  href?: string;
  /** An unread count. 0 or undefined hides it. */
  badge?: number;
  /** One key pressed with ⌘ or Ctrl, like `"K"`. Shown on hover and in the tooltip; handled when `shortcuts` is on. */
  shortcut?: string;
  /** A word or two at the row's end, read after the label: a teammate's status ("Away"), a state. */
  detail?: string;
};

/** An item in a section; with `items` it's a group that opens to show them, one level deep. */
export type SidebarSectionItem = SidebarItem & {
  items?: SidebarItem[];
  /** A group starts open. */
  defaultOpen?: boolean;
};

export type SidebarSection = {
  id: string;
  /** The small heading. Without one the items follow straight on. */
  label?: string;
  items: SidebarSectionItem[];
  /** The heading folds the section away. */
  collapsible?: boolean;
  /** A collapsible section starts open; true by default. */
  defaultOpen?: boolean;
};

export type SidebarRecentItem = {
  id: string;
  title: string;
  href?: string;
  /** Pinned items list above the rest, under their own heading. */
  pinned?: boolean;
  /** Quiet detail at the row's end: a relative time ("2h"), a small avatar group. The "…" takes its place while it shows. */
  meta?: ReactNode;
};

export type SidebarRecent = {
  /** Heading of the list; "Recent" by default. */
  label?: string;
  /** Heading of the pinned items; "Pinned" by default. */
  pinnedLabel?: string;
  items: SidebarRecentItem[];
  /** Holds the list's place with skeleton rows, after 300ms. */
  loading?: boolean;
  /** Announced while loading: "Loading chats…". */
  loadingLabel?: string;
  /** What shows with no items: one quiet line or two. */
  empty?: ReactNode;
  /** Rename in place. Return a promise to show saving; reject with a message to show it. */
  onRename?: (id: string, title: string) => void | Promise<unknown>;
  onPinnedChange?: (id: string, pinned: boolean) => void;
  /** Delete at once; ask first or offer Undo yourself. */
  onDelete?: (id: string) => void;
  /** A link (or button) after the list, to the full history. */
  showAll?: { label?: string; href?: string; onClick?: () => void };
};

/* ---------- State ---------- */

type SidebarState = {
  /** The sidebar element's id, for the toggle's aria-controls. */
  id: string;
  collapsed: boolean;
  setCollapsed: (collapsed: boolean) => void;
  /** Below the breakpoint: the sidebar is a drawer. */
  mobile: boolean;
  drawerOpen: boolean;
  setDrawerOpen: (open: boolean) => void;
  /** Collapse or expand; on a phone, open or close the drawer. */
  toggle: () => void;
  shortcut: string | false;
};

const StateContext = createContext<SidebarState | null>(null);

/** The sidebar's state, for your own toggle or layout. Inside a `SidebarProvider`. */
export function useSidebar() {
  const state = use(StateContext);
  if (!state) throw new Error("useSidebar must be inside <SidebarProvider>.");
  return state;
}

function subscribeQuery(onChange: () => void) {
  const query = matchMedia(SIDEBAR_DRAWER_QUERY);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
}

type SidebarProviderProps = {
  /** Controlled: the sidebar is an icon rail. */
  collapsed?: boolean;
  defaultCollapsed?: boolean;
  onCollapsedChange?: (collapsed: boolean) => void;
  /** The key pressed with ⌘ or Ctrl to collapse and expand: `"b"` by default; `false` turns it off. */
  shortcut?: string | false;
  children: ReactNode;
};

/** Holds the collapsed state, so a `SidebarToggle` outside the sidebar (in the page's header) can reach it. */
export function SidebarProvider({
  collapsed: controlled,
  defaultCollapsed = false,
  onCollapsedChange,
  shortcut = "b",
  children,
}: SidebarProviderProps) {
  const id = `${useId()}-sidebar`;
  const [inner, setInner] = useState(defaultCollapsed);
  const collapsed = controlled ?? inner;
  const mobile = useSyncExternalStore(
    subscribeQuery,
    () => matchMedia(SIDEBAR_DRAWER_QUERY).matches,
    () => false,
  );
  const [drawerOpen, setDrawerOpen] = useState(false);
  // Leaving the phone layout closes the drawer, so it can't reappear later.
  if (!mobile && drawerOpen) setDrawerOpen(false);

  const setCollapsed = useCallback(
    (next: boolean) => {
      if (controlled === undefined) setInner(next);
      onCollapsedChange?.(next);
    },
    [controlled, onCollapsedChange],
  );

  const toggle = useCallback(() => {
    if (mobile) setDrawerOpen((open) => !open);
    else setCollapsed(!collapsed);
  }, [mobile, collapsed, setCollapsed]);

  useEffect(() => {
    if (!shortcut) return;
    const onKey = (e: globalThis.KeyboardEvent) => {
      // A rich text editor that uses the same keys (bold) prevents the default first.
      if (e.defaultPrevented || e.repeat || e.altKey || e.shiftKey || !(e.metaKey || e.ctrlKey)) return;
      if (e.key.toLowerCase() !== shortcut.toLowerCase()) return;
      e.preventDefault();
      toggle();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [shortcut, toggle]);

  const value = useMemo(
    () => ({ id, collapsed, setCollapsed, mobile, drawerOpen, setDrawerOpen, toggle, shortcut }),
    [id, collapsed, setCollapsed, mobile, drawerOpen, toggle, shortcut],
  );
  return <StateContext value={value}>{children}</StateContext>;
}

/** A `dir` attribute changing anywhere above the sidebar. */
function subscribeDirection(onChange: () => void) {
  const observer = new MutationObserver(onChange);
  observer.observe(document.documentElement, { attributes: true, attributeFilter: ["dir"], subtree: true });
  return () => observer.disconnect();
}

/* What the header and footer buttons need to know about where they sit. */
type Slot = { collapsed: boolean; rtl: boolean; drawer: boolean };
const SlotContext = createContext<Slot>({ collapsed: false, rtl: false, drawer: false });

/* ---------- Sidebar ---------- */

type SidebarProps = {
  /** Names the `nav` landmark: "Main" by default. */
  "aria-label"?: string;
  /** The top: usually a `SidebarSwitcher`. On a phone it's the drawer's title. */
  header?: ReactNode;
  /** The bottom: usually a `SidebarAccount`. */
  footer?: ReactNode;
  /** The primary items, pinned under the header. They stay in the collapsed rail. */
  items: SidebarItem[];
  /** Headed groups of items below them; hidden in the collapsed rail. */
  sections?: SidebarSection[];
  /** A recent list, like chat history, after the sections. */
  recent?: SidebarRecent;
  /** The id of the current item, section item or recent item. */
  value?: string;
  /** Called with an id when an item is pressed (or its shortcut is). */
  onValueChange?: (id: string) => void;
  /** Handle ⌘ or Ctrl plus each item's `shortcut` anywhere on the page. */
  shortcuts?: boolean;
  className?: string;
};

/** The app sidebar: a switcher, items, sections, a recent list and an account; collapses to an icon rail, and is a drawer on phones. */
export function Sidebar(props: SidebarProps) {
  const state = use(StateContext);
  if (!state)
    return (
      <SidebarProvider>
        <SidebarFrame {...props} />
      </SidebarProvider>
    );
  return <SidebarFrame {...props} />;
}

function SidebarFrame({
  "aria-label": label = "Main",
  header,
  footer,
  items,
  sections = [],
  recent,
  value,
  onValueChange,
  shortcuts = false,
  className,
}: SidebarProps) {
  const state = useSidebar();
  const [root, setRoot] = useState<HTMLElement | null>(null);
  // The direction can change with the page around it; menus open toward the content.
  const rtl = useSyncExternalStore(
    subscribeDirection,
    () => (root ? getComputedStyle(root).direction === "rtl" : false),
    () => false,
  );

  const { mobile, setDrawerOpen } = state;
  const select = useCallback(
    (id: string) => {
      onValueChange?.(id);
      if (mobile) setDrawerOpen(false);
    },
    [onValueChange, mobile, setDrawerOpen],
  );

  // ⌘ or Ctrl plus a shortcut presses that item, so a link navigates and a button selects.
  useEffect(() => {
    if (!shortcuts) return;
    const all = [...items, ...sections.flatMap((s) => s.items.flatMap((i) => [i, ...(i.items ?? [])]))];
    const onKey = (e: globalThis.KeyboardEvent) => {
      if (e.defaultPrevented || e.altKey || e.shiftKey || !(e.metaKey || e.ctrlKey)) return;
      const item = all.find((i) => i.shortcut && i.shortcut.toLowerCase() === e.key.toLowerCase());
      if (!item) return;
      e.preventDefault();
      const el = document.querySelector<HTMLElement>(
        `[data-sidebar-id="${state.id}"] [data-id="${CSS.escape(item.id)}"]`,
      );
      if (el) el.click();
      else select(item.id);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [shortcuts, items, sections, select, state.id]);

  const collapsed = !mobile && state.collapsed;

  const nav = (
    <SidebarNav
      label={label}
      items={items}
      sections={sections}
      recent={recent}
      value={value}
      onSelect={select}
      collapsed={collapsed}
      drawer={mobile}
    />
  );

  // Menus and the rail's tooltip portal out of the sidebar; this gives them its direction.
  const direction = rtl ? "rtl" : "ltr";

  if (mobile) {
    return (
      <DirectionProvider direction={direction}>
        {/* Nothing else of the sidebar is in the page here; this reads its direction. */}
        <span ref={setRoot} hidden />
        <SlotContext value={{ collapsed: false, rtl, drawer: true }}>
          <NavRailTooltipGroup>
            {/* The drawer portals out of the page, so its parts carry the direction. */}
            <Drawer
              open={state.drawerOpen}
              onOpenChange={setDrawerOpen}
              side="start"
              size="sm"
              title={
                <span dir={direction} data-rtl={rtl || undefined}>
                  {header ?? label}
                </span>
              }
              footer={
                footer ? (
                  <div className={styles.drawerFooter} dir={direction} data-rtl={rtl || undefined}>
                    {footer}
                  </div>
                ) : undefined
              }
              className={`${styles.vars} ${styles.drawer}`}
            >
              <div data-sidebar-id={state.id} dir={direction} data-rtl={rtl || undefined}>
                {nav}
              </div>
            </Drawer>
          </NavRailTooltipGroup>
        </SlotContext>
      </DirectionProvider>
    );
  }

  return (
    <div
      ref={setRoot}
      id={state.id}
      data-sidebar-id={state.id}
      data-collapsed={collapsed || undefined}
      data-rtl={rtl || undefined}
      className={className ? `${styles.vars} ${styles.sidebar} ${className}` : `${styles.vars} ${styles.sidebar}`}
    >
      <DirectionProvider direction={direction}>
        <NavRailTooltipGroup root={root}>
          <SlotContext value={{ collapsed, rtl, drawer: false }}>
            {header && <div className={styles.header}>{header}</div>}
            {nav}
            {footer && <div className={styles.footer}>{footer}</div>}
          </SlotContext>
        </NavRailTooltipGroup>
      </DirectionProvider>
    </div>
  );
}

/* ---------- Nav ---------- */

type NavProps = {
  label: string;
  items: SidebarItem[];
  sections: SidebarSection[];
  recent?: SidebarRecent;
  value?: string;
  onSelect: (id: string) => void;
  collapsed: boolean;
  drawer: boolean;
};

const ITEM = "[data-sidebar-item]";

function usable(el: Element) {
  return el.getClientRects().length > 0 && !el.closest("[inert]");
}

/** Inside its scroll region's visible box, so a pill flying there isn't drawn over the fade. */
function inView(el: Element) {
  const viewport = el.closest("[data-sidebar-scroll]")?.firstElementChild;
  if (!viewport) return true;
  const box = el.getBoundingClientRect();
  const view = viewport.getBoundingClientRect();
  return box.top >= view.top && box.bottom <= view.bottom;
}

/**
 * The current row paints its own flat pill. When the current item changes,
 * one pill flies from the old row to the new one, as Tabs' does, then hands
 * back. Rows of different widths, hidden rows and reduced motion just switch.
 */
function usePillFlight(
  navRef: RefObject<HTMLElement | null>,
  pillRef: RefObject<HTMLSpanElement | null>,
  value?: string,
) {
  const previous = useRef(value);
  useLayoutEffect(() => {
    const nav = navRef.current;
    const pill = pillRef.current;
    const from = previous.current;
    previous.current = value;
    if (!nav || !pill || !from || !value || from === value) return;
    const find = (id: string) => nav.querySelector<HTMLElement>(`[data-pill][data-id="${CSS.escape(id)}"]`);
    const a = find(from);
    const b = find(value);
    const land = () => nav.removeAttribute("data-flying");
    if (!a || !b || !usable(a) || !usable(b) || !inView(a) || !inView(b)) {
      stopPill(pill, true);
      land();
      return;
    }
    const origin = nav.getBoundingClientRect();
    const ra = a.getBoundingClientRect();
    const rb = b.getBoundingClientRect();
    if (Math.abs(ra.left - rb.left) > 1 || Math.abs(ra.width - rb.width) > 1) {
      stopPill(pill, true);
      land();
      return;
    }
    const start = stopPill(pill, true) ?? { start: ra.top - origin.top, length: ra.height };
    const to = { start: rb.top - origin.top, length: rb.height };
    pill.style.left = `${rb.left - origin.left}px`;
    pill.style.width = `${rb.width}px`;
    pill.style.height = `${rb.height}px`;
    pill.style.transform = `translate(0px, ${to.start}px)`;
    nav.setAttribute("data-flying", "");
    flyPill(pill, start, to, true);
    const flight = pill.getAnimations()[0];
    if (!flight) return land();
    // A newer flight cancels this one, which rejects; that flight lands itself.
    flight.finished.then(land, () => {});
  }, [navRef, pillRef, value]);
}

function SidebarNav({ label, items, sections, recent, value, onSelect, collapsed, drawer }: NavProps) {
  const navRef = useRef<HTMLElement>(null);
  const pillRef = useRef<HTMLSpanElement>(null);
  usePillFlight(navRef, pillRef, value);

  // Up and Down, Home and End move between rows; Tab still visits every control.
  function onKeyDown(e: KeyboardEvent<HTMLElement>) {
    if (!["ArrowUp", "ArrowDown", "Home", "End"].includes(e.key)) return;
    if ((e.target as HTMLElement).closest("input, textarea")) return;
    const all = [...e.currentTarget.querySelectorAll<HTMLElement>(ITEM)].filter(usable);
    const at = all.indexOf(document.activeElement as HTMLElement);
    if (at === -1) return;
    e.preventDefault();
    const to =
      e.key === "Home"
        ? 0
        : e.key === "End"
          ? all.length - 1
          : Math.min(Math.max(at + (e.key === "ArrowDown" ? 1 : -1), 0), all.length - 1);
    all[to]?.focus();
  }

  const hasMore = sections.length > 0 || recent;
  const more = hasMore && (
    <>
      {sections.map((section) => (
        <Section key={section.id} section={section} value={value} onSelect={onSelect} />
      ))}
      {recent && <Recent recent={recent} value={value} onSelect={onSelect} />}
    </>
  );

  return (
    <nav ref={navRef} aria-label={label} className={styles.nav} onKeyDown={onKeyDown}>
      <span ref={pillRef} className={styles.pill} aria-hidden="true" />
      <ul className={styles.primary}>
        {items.map((item) => (
          <li key={item.id} className={styles.cell}>
            <ItemRow item={item} current={item.id === value} onSelect={onSelect} tooltip={collapsed} />
          </li>
        ))}
      </ul>
      {hasMore &&
        (drawer ? (
          <div className={styles.more}>{more}</div>
        ) : (
          <div className={styles.scrollWrap} inert={collapsed} data-sidebar-scroll="">
            <ScrollArea className={styles.scroll}>
              <div className={styles.more}>{more}</div>
            </ScrollArea>
          </div>
        ))}
    </nav>
  );
}

/* ---------- Rows ---------- */

type ItemRowProps = {
  item: SidebarItem;
  current: boolean;
  onSelect: (id: string) => void;
  /** Collapsed: the rail's tooltip names it. */
  tooltip?: boolean;
  nested?: boolean;
};

function ItemRow({ item, current, onSelect, tooltip = false, nested = false }: ItemRowProps) {
  const count = item.badge && item.badge > 0 ? item.badge : 0;
  const shown = count > 99 ? "99+" : String(count);
  const props = {
    className: styles.row,
    "data-sidebar-item": "",
    "data-pill": "",
    "data-id": item.id,
    "data-nested": nested || undefined,
    "data-current": current || undefined,
    "aria-current": current ? ("page" as const) : undefined,
    "aria-label": count || item.detail ? [item.label, item.detail, count ? `${count} new` : ""].filter(Boolean).join(", ") : undefined,
    "aria-keyshortcuts": item.shortcut ? `Meta+${item.shortcut} Control+${item.shortcut}` : undefined,
    onClick: () => onSelect(item.id),
  };
  const body = (
    <>
      {item.icon && (
        <span className={styles.icon} aria-hidden="true">
          {item.icon}
        </span>
      )}
      <span className={styles.label}>{item.label}</span>
      {(item.shortcut || item.detail || count > 0) && (
        <span className={styles.trailing} aria-hidden="true">
          {item.detail && <span className={styles.detail}>{item.detail}</span>}
          {item.shortcut && <Kbd className={styles.kbd} keys={["mod", item.shortcut]} variant="plain" size="sm" />}
          {count > 0 && <span className={styles.count}>{shown}</span>}
        </span>
      )}
      {count > 0 && (
        <span className={styles.corner} aria-hidden="true">
          {shown}
        </span>
      )}
    </>
  );
  return (
    <NavRailTrigger label={item.label} shortcut={item.shortcut} disabled={!tooltip}>
      {item.href ? (
        <a href={item.href} {...props}>
          {body}
        </a>
      ) : (
        <button type="button" {...props}>
          {body}
        </button>
      )}
    </NavRailTrigger>
  );
}

/** Opens and closes on height: grid rows 0fr → 1fr, its content inert while closed. */
function Fold({ open, id, children }: { open: boolean; id?: string; children: ReactNode }) {
  return (
    <div className={styles.fold} data-open={open || undefined} inert={!open}>
      <div id={id} className={styles.foldInner}>
        {children}
      </div>
    </div>
  );
}

function Chevron({ open }: { open: boolean }) {
  // Content opens below the row, so it points down and turns up. It morphs; it never spins.
  return <Icon name={open ? "chevron-up" : "chevron-down"} className={styles.chevron} />;
}

function GroupRow({
  item,
  value,
  onSelect,
}: {
  item: SidebarSectionItem;
  value?: string;
  onSelect: (id: string) => void;
}) {
  const children = item.items ?? [];
  const [open, setOpen] = useState(item.defaultOpen ?? children.some((c) => c.id === value));
  const listId = `${useId()}-items`;
  return (
    <>
      <button
        type="button"
        className={styles.row}
        data-sidebar-item=""
        aria-expanded={open}
        aria-controls={listId}
        onClick={() => setOpen(!open)}
      >
        {item.icon && (
          <span className={styles.icon} aria-hidden="true">
            {item.icon}
          </span>
        )}
        <span className={styles.label}>{item.label}</span>
        <Chevron open={open} />
      </button>
      <Fold open={open}>
        <ul id={listId} className={styles.list}>
          {children.map((child) => (
            <li key={child.id} className={styles.cell}>
              <ItemRow item={child} current={child.id === value} onSelect={onSelect} nested />
            </li>
          ))}
        </ul>
      </Fold>
    </>
  );
}

function Section({
  section,
  value,
  onSelect,
}: {
  section: SidebarSection;
  value?: string;
  onSelect: (id: string) => void;
}) {
  const [open, setOpen] = useState(section.defaultOpen ?? true);
  const id = useId();
  const headingId = `${id}-heading`;
  const listId = `${id}-list`;
  const list = (
    <ul id={listId} className={styles.list}>
      {section.items.map((item) => (
        <li key={item.id} className={styles.cell}>
          {item.items?.length ? (
            <GroupRow item={item} value={value} onSelect={onSelect} />
          ) : (
            <ItemRow item={item} current={item.id === value} onSelect={onSelect} />
          )}
        </li>
      ))}
    </ul>
  );
  return (
    <section className={styles.section} aria-labelledby={section.label ? headingId : undefined}>
      {section.label && (
        <h2 id={headingId} className={styles.heading}>
          {section.collapsible ? (
            <button
              type="button"
              className={styles.headingButton}
              data-sidebar-item=""
              aria-expanded={open}
              aria-controls={listId}
              onClick={() => setOpen(!open)}
            >
              <span className={styles.headingLabel}>{section.label}</span>
              <Chevron open={open} />
            </button>
          ) : (
            <span className={styles.headingText}>{section.label}</span>
          )}
        </h2>
      )}
      {section.collapsible ? <Fold open={open}>{list}</Fold> : list}
    </section>
  );
}

/* ---------- Recent ---------- */

type RowState = "in" | "enter" | "leave";
type Row = { item: SidebarRecentItem; state: RowState };

/** Removed items stay a moment to fade and fold; new ones open in. */
function merge(previous: Row[], items: SidebarRecentItem[]): Row[] {
  const was = new Map(previous.filter((r) => r.state !== "leave").map((r) => [r.item.id, r.state]));
  const ids = new Set(items.map((i) => i.id));
  const next: Row[] = items.map((item) => {
    const state = was.get(item.id);
    return { item, state: state === undefined ? "enter" : state === "enter" ? "enter" : "in" };
  });
  previous.forEach((row, i) => {
    if (ids.has(row.item.id)) return;
    let at = 0;
    for (let j = i - 1; j >= 0; j--) {
      const k = next.findIndex((n) => n.item.id === previous[j].item.id);
      if (k !== -1) {
        at = k + 1;
        break;
      }
    }
    next.splice(at, 0, { item: row.item, state: "leave" });
  });
  return next;
}

/** The fade (120ms) then the fold (200ms), with a little room. */
const LEAVE_MS = 360;

function useRows(items: SidebarRecentItem[]) {
  const [rows, setRows] = useState<Row[]>(() => items.map((item) => ({ item, state: "in" })));
  const [last, setLast] = useState(items);
  if (items !== last) {
    setLast(items);
    setRows(merge(rows, items));
  }
  const leaving = rows.some((r) => r.state === "leave");
  useEffect(() => {
    if (!leaving) return;
    const timer = window.setTimeout(() => setRows((all) => all.filter((r) => r.state !== "leave")), LEAVE_MS);
    return () => window.clearTimeout(timer);
  }, [leaving, rows]);
  return rows;
}

function PinGlyph() {
  return (
    <svg className={styles.glyph} viewBox="0 0 16 16" aria-hidden="true">
      <path d="M5.25 2.75h5.5M6.5 2.75v3.5l-2 3h7l-2-3v-3.5M8 9.25v4" />
    </svg>
  );
}

function Recent({
  recent,
  value,
  onSelect,
}: {
  recent: SidebarRecent;
  value?: string;
  onSelect: (id: string) => void;
}) {
  const { items, loading = false } = recent;
  const pinned = useMemo(() => items.filter((i) => i.pinned), [items]);
  const rest = useMemo(() => items.filter((i) => !i.pinned), [items]);
  const [editing, setEditing] = useState<string | null>(null);
  const label = recent.label ?? "Recent";

  const skeleton = (
    <div className={styles.skeleton}>
      {["72%", "54%", "80%", "46%", "64%"].map((width, i) => (
        <div key={i} className={styles.skeletonRow}>
          <SkeletonText size="sm" width={width} />
        </div>
      ))}
    </div>
  );

  const group = (heading: string, list: SidebarRecentItem[], always: boolean) => (
    <RecentGroup
      key={heading}
      heading={heading}
      items={list}
      always={always}
      recent={recent}
      value={value}
      editing={editing}
      setEditing={setEditing}
      onSelect={onSelect}
    />
  );

  return (
    <>
      {!loading && pinned.length > 0 && group(recent.pinnedLabel ?? "Pinned", pinned, false)}
      <section className={styles.section} aria-label={loading || items.length === 0 ? label : undefined}>
        {(loading || items.length === 0) && (
          <h2 className={styles.heading}>
            <span className={styles.headingText}>{label}</span>
          </h2>
        )}
        <SkeletonGroup loading={loading} fallback={skeleton} label={recent.loadingLabel ?? "Loading…"}>
          {items.length === 0 ? (
            <div className={styles.empty}>{recent.empty ?? <p className={styles.emptyTitle}>Nothing here yet</p>}</div>
          ) : (
            group(label, rest, true)
          )}
        </SkeletonGroup>
      </section>
    </>
  );
}

type RecentGroupProps = {
  heading: string;
  items: SidebarRecentItem[];
  /** Keep the group (and Show all) when every item is pinned. */
  always: boolean;
  recent: SidebarRecent;
  value?: string;
  editing: string | null;
  setEditing: (id: string | null) => void;
  onSelect: (id: string) => void;
};

function RecentGroup({ heading, items, always, recent, value, editing, setEditing, onSelect }: RecentGroupProps) {
  const rows = useRows(items);
  const headingId = `${useId()}-heading`;
  const listRef = useRef<HTMLUListElement>(null);
  if (!always && rows.length === 0) return null;
  const { showAll } = recent;

  // Focus moves to the next chat (or the one before) once the menu has let go.
  function remove(id: string) {
    const list = listRef.current;
    const lis = list ? [...list.querySelectorAll<HTMLElement>(":scope > li:not([data-state='leave'])")] : [];
    const at = lis.findIndex((li) => li.dataset.id === id);
    const target = (lis[at + 1] ?? lis[at - 1])?.querySelector<HTMLElement>(ITEM);
    recent.onDelete?.(id);
    window.setTimeout(() => {
      if (target?.isConnected) target.focus();
      else list?.closest("nav")?.querySelector<HTMLElement>(ITEM)?.focus();
    }, 180);
  }

  const inner = (
    <>
      <h2 id={headingId} className={styles.heading}>
        <span className={styles.headingText}>{heading}</span>
      </h2>
      {rows.length > 0 && (
        <ul ref={listRef} className={styles.list}>
          {rows.map(({ item, state }) => (
            <RecentRow
              key={item.id}
              item={item}
              state={state}
              current={item.id === value}
              editing={editing === item.id}
              recent={recent}
              onSelect={onSelect}
              onStartRename={() => setEditing(item.id)}
              onEndRename={() => setEditing(null)}
              onDelete={() => remove(item.id)}
            />
          ))}
        </ul>
      )}
      {always &&
        showAll &&
        (showAll.href ? (
          <a className={styles.showAll} href={showAll.href} onClick={showAll.onClick} data-sidebar-item="">
            {showAll.label ?? "Show all"}
          </a>
        ) : (
          <button type="button" className={styles.showAll} onClick={showAll.onClick} data-sidebar-item="">
            {showAll.label ?? "Show all"}
          </button>
        ))}
    </>
  );

  return always ? (
    <div className={styles.section}>{inner}</div>
  ) : (
    <section className={styles.section} aria-labelledby={headingId}>
      {inner}
    </section>
  );
}

type RecentRowProps = {
  item: SidebarRecentItem;
  state: RowState;
  current: boolean;
  editing: boolean;
  recent: SidebarRecent;
  onSelect: (id: string) => void;
  onStartRename: () => void;
  onEndRename: () => void;
  onDelete: () => void;
};

function RecentRow({
  item,
  state,
  current,
  editing,
  recent,
  onSelect,
  onStartRename,
  onEndRename,
  onDelete,
}: RecentRowProps) {
  const [menuOpen, setMenuOpen] = useState(false);
  const rowRef = useRef<HTMLElement>(null);
  const { onRename, onPinnedChange, onDelete: canDelete } = recent;
  const actions = Boolean(onRename || onPinnedChange || canDelete);
  const props = {
    className: styles.row,
    "data-kind": "recent",
    "data-sidebar-item": "",
    "data-pill": "",
    "data-id": item.id,
    "data-current": current || undefined,
    "aria-current": current ? ("page" as const) : undefined,
    // The title may be cut; the whole of it is here too.
    title: item.title,
    onClick: () => onSelect(item.id),
  };
  // Titles are people's own words, in any script: each takes its own direction.
  const title = (
    <>
      <span className={styles.recentTitle} dir="auto">
        {item.title}
      </span>
      {item.meta && <span className={styles.recentMeta}>{item.meta}</span>}
    </>
  );

  return (
    <li
      className={styles.recentItem}
      data-id={item.id}
      data-state={state === "in" ? undefined : state}
      data-menu-open={menuOpen || undefined}
      data-actions={actions || undefined}
      data-meta={item.meta ? true : undefined}
      inert={state === "leave"}
    >
      <div className={styles.recentInner}>
        {editing && onRename ? (
          <RenameField
            initial={item.title}
            onCommit={(next) => onRename(item.id, next)}
            onDone={(refocus) => {
              onEndRename();
              if (refocus) requestAnimationFrame(() => rowRef.current?.focus());
            }}
          />
        ) : (
          <>
            {item.href ? (
              <a ref={rowRef as RefObject<HTMLAnchorElement>} href={item.href} {...props}>
                {title}
              </a>
            ) : (
              <button ref={rowRef as RefObject<HTMLButtonElement>} type="button" {...props}>
                {title}
              </button>
            )}
            {actions && (
              <DropdownMenu
                align="end"
                open={menuOpen}
                onOpenChange={setMenuOpen}
                trigger={
                  <button type="button" className={styles.moreButton} aria-label={`Actions for ${item.title}`}>
                    <Icon name="more" />
                  </button>
                }
              >
                {onRename && (
                  <MenuItem icon={<Icon name="pencil" />} onSelect={onStartRename}>
                    Rename
                  </MenuItem>
                )}
                {onPinnedChange && (
                  <MenuItem icon={<PinGlyph />} onSelect={() => onPinnedChange(item.id, !item.pinned)}>
                    {item.pinned ? "Unpin" : "Pin"}
                  </MenuItem>
                )}
                {canDelete && (
                  <>
                    {(onRename || onPinnedChange) && <MenuSeparator />}
                    <MenuItem variant="danger" icon={<Icon name="trash" />} onSelect={onDelete}>
                      Delete
                    </MenuItem>
                  </>
                )}
              </DropdownMenu>
            )}
          </>
        )}
      </div>
    </li>
  );
}

type RenameFieldProps = {
  initial: string;
  onCommit: (title: string) => void | Promise<unknown>;
  /** `refocus`: the field had focus, so hand it back to the row. */
  onDone: (refocus: boolean) => void;
};

/** The row's title, editable where it sits. Enter or leaving saves, Escape cancels. */
function RenameField({ initial, onCommit, onDone }: RenameFieldProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [draft, setDraft] = useState(initial);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const errorId = `${useId()}-error`;
  const done = useRef(false);

  // The menu hands focus back to its trigger as it closes; take it after that.
  useEffect(() => {
    const frame = requestAnimationFrame(() => {
      inputRef.current?.focus();
      inputRef.current?.select();
    });
    return () => cancelAnimationFrame(frame);
  }, []);

  function finish(refocus: boolean) {
    if (done.current) return;
    done.current = true;
    onDone(refocus);
  }

  async function commit(refocus: boolean) {
    if (busy || done.current) return;
    const next = draft.trim();
    if (!next) {
      setError("Enter a name");
      inputRef.current?.focus();
      return;
    }
    if (next === initial) return finish(refocus);
    let result: void | Promise<unknown>;
    try {
      result = onCommit(next);
    } catch (reason) {
      setError(reason instanceof Error && reason.message ? reason.message : "Couldn’t rename. Try again.");
      return;
    }
    if (!(result instanceof Promise)) return finish(refocus);
    setBusy(true);
    setError(null);
    try {
      await result;
      finish(refocus);
    } catch (reason) {
      setBusy(false);
      setError(
        typeof reason === "string" && reason
          ? reason
          : reason instanceof Error && reason.message
            ? reason.message
            : "Couldn’t rename. Try again.",
      );
      inputRef.current?.focus();
    }
  }

  function onKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (event.nativeEvent.isComposing) return;
    if (event.key === "Enter") {
      event.preventDefault();
      void commit(true);
    } else if (event.key === "Escape") {
      // Kept here, so a drawer around the list stays open.
      event.preventDefault();
      event.stopPropagation();
      if (!busy) finish(true);
    }
  }

  return (
    <div className={styles.rename}>
      <input
        ref={inputRef}
        className={busy ? `${styles.renameInput} ${styles.renameBusy}` : styles.renameInput}
        value={draft}
        dir="auto"
        maxLength={120}
        aria-label="Name"
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? errorId : undefined}
        aria-busy={busy || undefined}
        readOnly={busy}
        enterKeyHint="done"
        onChange={(e) => {
          setDraft(e.currentTarget.value);
          setError(null);
        }}
        onKeyDown={onKeyDown}
        onBlur={() => {
          if (!error) void commit(false);
        }}
      />
      {error && (
        <p id={errorId} className={styles.renameError} role="alert">
          {error}
        </p>
      )}
    </div>
  );
}

/* ---------- Header and footer ---------- */

type MenuButtonProps = {
  /** The 24px mark or avatar at the start; it's what the collapsed rail shows. */
  media: ReactNode;
  name: string;
  /** A second line: a plan, an email. */
  detail?: string;
  /** Menu items: `MenuItem`, `MenuRadioGroup`, `MenuSeparator`… */
  children: ReactNode;
  kind: "switcher" | "account";
};

function MenuButton({ media, name, detail, children, kind }: MenuButtonProps) {
  const slot = use(SlotContext);
  const [open, setOpen] = useState(false);
  const below = kind === "switcher";
  // Collapsed, the menu opens beside the rail, toward the content.
  const side = slot.collapsed ? (slot.rtl ? "left" : "right") : below ? "bottom" : "top";
  // The chevron points where the menu opens, and turns as it does.
  const pointsDown = below ? !open : open;
  return (
    <DropdownMenu
      side={side}
      align={slot.collapsed && !below ? "end" : "start"}
      open={open}
      onOpenChange={setOpen}
      className={styles.menu}
      trigger={
        <NavRailTrigger label={name} disabled={!slot.collapsed}>
          <button type="button" className={styles.menuButton} data-kind={kind}>
            <span className={styles.media} data-kind={kind} aria-hidden="true">
              {media}
            </span>
            <span className={styles.menuText}>
              <span className={styles.menuName} dir="auto" title={name}>
                {name}
              </span>
              {detail && (
                <span className={styles.menuDetail} dir="auto">
                  {detail}
                </span>
              )}
            </span>
            <Icon name={pointsDown ? "chevron-down" : "chevron-up"} className={styles.chevron} />
          </button>
        </NavRailTrigger>
      }
    >
      {children}
    </DropdownMenu>
  );
}

type SidebarSwitcherProps = {
  /** The workspace or app mark, drawn on a round ink tile. */
  mark: ReactNode;
  name: string;
  detail?: string;
  /** Menu items: the workspaces as a `MenuRadioGroup`, then settings. */
  children: ReactNode;
};

/** The header's workspace or app switcher: mark, name and a chevron, opening a menu. */
export function SidebarSwitcher({ mark, name, detail, children }: SidebarSwitcherProps) {
  return (
    <MenuButton kind="switcher" media={<span className={styles.mark}>{mark}</span>} name={name} detail={detail}>
      {children}
    </MenuButton>
  );
}

type SidebarAccountProps = {
  /** A 24px `Avatar`, decorative: the name is written beside it. */
  avatar: ReactNode;
  name: string;
  /** The plan or email under the name. */
  detail?: string;
  /** Menu items: settings, help, log out. */
  children: ReactNode;
};

/** The footer's account row: avatar, name and plan, opening a menu above it. */
export function SidebarAccount({ avatar, name, detail, children }: SidebarAccountProps) {
  return (
    <MenuButton kind="account" media={avatar} name={name} detail={detail}>
      {children}
    </MenuButton>
  );
}

/** Collapses and expands the sidebar, or opens it on a phone. Put it in the page's header or the sidebar's. */
export function SidebarToggle({ className }: { className?: string }) {
  const state = useSidebar();
  const label = state.mobile ? "Open sidebar" : state.collapsed ? "Expand sidebar" : "Collapse sidebar";
  const key = state.shortcut ? state.shortcut.toUpperCase() : null;
  return (
    <Tooltip
      describe={false}
      content={
        <span className={styles.tip}>
          {label}
          {key && <Kbd className={styles.tipKbd} keys={["mod", key]} variant="plain" size="sm" />}
        </span>
      }
    >
      <Button
        variant="ghost"
        size="sm"
        className={className}
        aria-label={label}
        aria-expanded={state.mobile ? state.drawerOpen : !state.collapsed}
        aria-controls={state.mobile ? undefined : state.id}
        aria-haspopup={state.mobile ? "dialog" : undefined}
        aria-keyshortcuts={key ? `Meta+${key} Control+${key}` : undefined}
        onClick={state.toggle}
      >
        <Icon name="sidebar" />
      </Button>
    </Tooltip>
  );
}
